INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('ai-measurements-of-heart-scans-predicted-surviva', 'new', 'good', '2026-11-11', 'AI measurements of heart scans predicted survival slightly better than doctors'' measurements, in seconds', 'Researchers at City St George''s, University of London and University College London compared an AI tool with experienced clinicians at measuring how well the heart pumps from MRI scans of 27,382 patients in the UK and the United States. Most scans came from Barts Heart Centre in London, and 3,458 patients died over a median follow-up of 5.6 years. The AI''s measurements were slightly but significantly better at predicting who died, and the study was published in The Lancet Digital Health on 2 November 2026.', 'The AI did in about 2 to 3 seconds per patient a measurement that takes an expert around 13 minutes, and its numbers were at least as good a guide to survival. The researchers support using it as a first check on heart MRI scans, with experts reviewing where needed.', NULL, NULL, '["The gain is small: a C index of 0.781 for the AI against 0.777 for clinicians", "It looked back at old scans, so it shows a link with survival, not that using the tool helps patients live longer", "The tool is not described as being in routine use", "The 2 to 3 seconds against 13 minutes figure comes from the team''s earlier work, not from this study", "The senior author invented the tool", "About 1% of patients had an AI error, so clinicians still need to check"]', 'health', 'in_the_lab', 'vision', 10, '["https://www.news-medical.net/news/20261102/AI-powered-heart-MRI-measurements-better-predict-patients-survival.aspx", "https://www.emjreviews.com/?p=612455"]', NULL, 'waiting', NULL, 0);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('ai-glasses-helped-a-blind-vietnam-veteran-find-h', 'new', 'good', '2026-11-11', 'AI glasses helped a blind Vietnam veteran find his friend''s name on the memorial wall', 'Veterans from across the United States, many of them blind or visually impaired, toured the war memorials in Washington DC on a three-day honour flight sponsored by Meta, reported on 11 November 2026. Each was given a pair of Ray-Ban Meta AI glasses, which use cameras, microphones and AI to describe what is in front of the wearer. Victor Dunham, a Vietnam veteran from Texas, said the glasses helped him find the name of his friend Anthony on the Vietnam Veterans Memorial wall after searching without success, and that he had ''closed that loop today''.', 'The AI described the memorials aloud to people who cannot see them, so a veteran could find a fallen friend''s name for himself. Blind and visually impaired veterans are the ones better off.', NULL, NULL, '["The trip and the glasses were paid for by Meta, which makes the glasses", "Meta says it plans to donate 130,000 pairs to blind and visually impaired veterans: that is a plan, not something done", "The report does not say how many veterans were on the trip", "Only the Vietnam Veterans Memorial is named", "The account of what the glasses did comes from Victor Dunham and from a Meta employee, not from a study"]', 'accessibility', 'helping_people_now', 'vision', 23, '["https://www.wcax.com/2026/11/11/veterans-tour-washington-war-memorials-using-ai-glasses/"]', NULL, 'waiting', NULL, 1);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('an-ai-operator-now-answers-most-non-emergency-ca', 'new', 'good', '2026-11-11', 'An AI operator now answers most non-emergency calls to the Citrus County sheriff, leaving 911 to people', 'The Citrus County Sheriff''s Office in Florida is using an AI operator to answer non-emergency calls at its emergency operations centre in Lecanto, Bay News 9 reported on 11 November 2026. The centre takes about 5,000 calls a week, and Sheriff David Vincent said the AI has handled about 60% of the non-emergency calls so far. Emergency 911 calls still go to human dispatchers, callers can ask for a person, and staff watch the AI calls in real time.', 'The AI takes routine calls so that human call takers are free for people who need help straight away. Residents with an emergency and the dispatchers themselves are the ones better off.', NULL, NULL, '["The AI does not answer 911 calls, only the non-emergency line, even though the article''s opening line says it screens 911 calls", "The 60% figure comes from the sheriff and has not been independently measured", "There is no evidence yet that emergency response got faster", "The article does not say when the system started or who makes it", "Some residents raised concerns, and a University of South Florida AI expert warned about replacing trained workers"]', 'everyday_life', 'helping_people_now', 'voice', 16, '["https://baynews9.com/fl/tampa/news/2026/11/11/citrus-county-sheriffs-office-using-ai-technology-to-help-screen-calls-save-time-for-those-emergencies-that-require-attention"]', NULL, 'waiting', NULL, 2);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('ai-let-scientists-watch-thousands-of-brain-cance', 'new', 'good', '2026-11-11', 'AI let scientists watch thousands of brain cancer cells spread through living tissue', 'Researchers at Uppsala University in Sweden built a method called GlioTrace that films slices of living mouse brain containing tumour cells from six glioblastoma patients for up to five days, then uses AI to follow thousands of individual cancer cells. They found that some tumours spread mainly along blood vessels while others spread more widely through the tissue, and that a single cell can switch between the two. The study was published in Nature Communications on 11 November 2026, and the software is free for other researchers.', 'The AI picks out and follows each cell across a whole brain slice, which showed for the first time how thousands of individual tumour cells move through living brain tissue. Cancer researchers now have a way to test what slows that spread.', NULL, NULL, '["The tissue was mouse brain slices carrying human tumour cells, not patients", "It is a research method, and the team says more studies are needed before it could guide treatment", "Two drug substances reduced cell movement in the slices, but they are unnamed and the effect varied between tumours: this is not a treatment", "Cells came from only six patients", "''For the first time'' is the researchers'' own claim"]', 'health', 'in_the_lab', 'vision', 9, '["https://www.mynewsdesk.com/uu/pressreleases/new-method-reveals-how-brain-cancer-cells-spread-3476334"]', NULL, 'waiting', NULL, 3);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('mayo-clinic-ai-predicts-what-a-kidney-stone-is-m', 'new', 'good', '2026-11-12', 'Mayo Clinic AI predicts what a kidney stone is made of from a routine urine test', 'Mayo Clinic researchers built an AI model that reads the many measurements in a standard 24-hour urine test, plus age and sex, to predict what type of kidney stone a patient has. It was built on data from more than 13,000 patients and tested on 1,653 others, where it was right for 73% of patients against 33% for the usual urine-based calculation. The study was published in Mayo Clinic Proceedings and announced on 12 November 2026.', 'The AI found patterns in a test patients already take, more than doubling how often the stone type was predicted correctly. That helps people whose stone was never caught for analysis, which the researchers say is common.', NULL, NULL, '["It is a research finding: the release does not say the model is in clinical use", "It is meant to add to existing results, not replace analysing a real stone", "73% still means roughly one in four predictions was wrong", "The figures come from Mayo Clinic''s own patients and its own release", "Do not say it spares patients procedures: the release does not claim that"]', 'health', 'in_the_lab', 'other', 10, '["https://www.newswise.com/articles/mayo-clinic-researchers-use-ai-to-better-predict-kidney-stone-composition"]', NULL, 'waiting', NULL, 4);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('an-ai-trained-on-photos-of-cats-dogs-and-cars-in', 'new', 'good', '2026-11-12', 'An AI trained on photos of cats, dogs and cars independently confirmed the first picture of a black hole', 'Four researchers at CSIRO, Australia''s national science agency, re-made the famous 2019 image of the black hole at the centre of the galaxy M87 using a new AI method called GenDIReCT. The AI was trained on everyday pictures such as cats, dogs and cars, so it had no idea what a black hole should look like, and it still produced a ring almost identical in size and shape to the original. The work was published in Nature and announced on 12 November 2026.', 'Scientists had asked how much the original picture was shaped by the way it was processed. An AI that had never seen a black hole reaching the same ring by a different route shows the ring is a real feature, which the director of the Event Horizon Telescope collaboration said is in excellent agreement with their results.', NULL, NULL, '["It reanalysed the same telescope data, it is not a new observation or a new photo", "Fine details such as the ring''s width and brightness differ a little between methods", "''First truly independent validation'' is the lead author''s own phrase", "The sources opened do not say the team is in Perth, so do not call them Perth scientists without checking", "The idea that the technique could help medical imaging or earthquake mapping is only a possibility raised by the team"]', 'space', 'in_the_lab', 'other', 18, '["https://www.csiro.au/en/news/All/News/2026/November/confirm-black-hole", "https://www.csiro.au/en/news/All/Articles/2026/November/Blackhole-Conversation"]', NULL, 'waiting', NULL, 5);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('ai-reads-what-emergency-room-patients-say-and-fl', 'new', 'good', '2026-11-13', 'AI reads what emergency room patients say and flags who is at risk of PTSD', 'Researchers at NYU Langone Health built an AI tool called PREVIA that reads a patient''s own answer to the question of what brought them to the emergency room. They tested it on the accounts of 145 injured patients at two New York trauma centres and checked it against a specialist interview one month later. It picked out about 95 in 100 of the patients who went on to have PTSD, and the study was published in Nature Communications on 9 November 2026.', 'The AI turned a routine question into an early warning and gave a plain explanation with each risk score. The NYU Langone page says only about 28% of emergency departments routinely screen for PTSD, so people who would otherwise be missed are the ones who stand to benefit.', NULL, NULL, '["It is a study, not a tool in use in any hospital", "Small study: 145 patients at two New York trauma centres, and the authors say larger independent validation is needed", "About half of the patients it flagged did not go on to have PTSD (precision about 47%)", "The comparison with a clinician used one specialist and 30 patients, so do not say it beats doctors; the paper says it performed comparably", "It predicts PTSD at one month, not longer", "It estimates risk, it does not diagnose or treat PTSD", "English-speaking patients only, and 31% of the sample were women"]', 'health', 'in_the_lab', 'language model', 14, '["https://nyulangone.org/news/ai-predicts-ptsd-risk-based-stories-about-what-brought-patients-emergency-room", "https://www.nature.com/articles/s41467-026-78768-3"]', NULL, 'waiting', NULL, 6);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('montreal-woman-with-als-speaks-in-her-own-voice', 'new', 'good', '2026-11-14', 'Montreal woman with ALS speaks in her own voice again through an AI app', 'Anne-Marie Poirier of Montreal has ALS and began losing her voice in October 2025. Since May 2026 she has used Vocality, an app built by two Montreal entrepreneurs, Thomas Houlachi and David Ruiz. She types a few keywords and the app turns them into full sentences, spoken aloud in a synthetic voice made from recordings of her own speech.', 'The AI does two things she could not do otherwise: it builds whole sentences from a few keywords and it speaks them in a voice that sounds like hers. Poirier told The Canadian Press, "It gives me energy, a feeling of being alive."', NULL, NULL, '["The voice is synthetic, made with ElevenLabs technology from her recordings; she has not regained natural speech", "The app launched on iPhone and iPad in June 2026, so the app itself is not new this week; the news is her story", "The figure of more than 100 daily users across North America comes from the company", "It is a paid subscription and the price is not given", "No clinician or outside expert assessed the app in the report", "She reported a bug where the app sometimes erased sentences after reading them", "The source opened is The Canadian Press via Global News, not the CBC article named in the shortlist"]', 'accessibility', 'helping_people_now', 'voice', 22, '["https://globalnews.ca/news/12147285/quebec-woman-als-ai-voice-app/"]', NULL, 'waiting', NULL, 7);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('south-korea-s-top-tax-exam-scorer-admits-cheatin', 'new', 'flip', '2026-11-14', 'South Korea''s top tax exam scorer admits cheating with AI, and the authorities move in', 'The top scorer in South Korea''s national tax accountant exam admitted in a video and in a written confession to police that he cheated in both rounds. He said he photographed the questions with a miniature camera, sent them to an AI tool and read the answers on his smartphone. The Seoul Metropolitan Police Agency has assigned the case to investigators, the exam body''s president apologised and said it would file a criminal complaint, and the presidential office decided to investigate all suspected AI cheating across national qualification exams.', 'The cheating came out in public and the system responded within days: police are investigating, the finance ministry is moving to suspend his certificate so he cannot practise, and checks for AI devices are planned for the college entrance exam on 19 November. Honest candidates are the ones this protects.', 'The man who came first in both rounds of South Korea''s national tax accountant exam, with 397.5 out of 400 in the first, got there by secretly using AI to answer the questions.', 'system_responding', '["He first denied cheating and confessed only after suspicion spread online, so do not present it as a prompt or voluntary confession", "The certificate suspension is being moved, not done; the ministry says a confession alone is not enough to revoke it", "The police investigation has only begun: no charge or conviction", "The exam body said it would file a criminal complaint; it is not confirmed as filed", "He says he used a miniature camera and a smartphone; smart glasses were the online suspicion, not what he admitted", "He also said he used the same method on the first stage of the public accountant exam", "The reports do not give his real name, so do not name him", "Do not suggest AI cheating has been solved"]', 'everyday_life', 'helping_people_now', 'language model', 18, '["https://www.koreajoongangdaily.com/korea/top-scorer-on-tax-accountant-exam-admits-using-ai-to-cheat/12973195", "https://www.arabnews.pk/world/south-korea-probes-top-exam-scorer-after-ai-cheating-confession-3007127", "https://mbiz.heraldcorp.com/article/10937701", "https://mbiz.heraldcorp.com/article/10937481", "https://www.khan.co.kr/en/article/202611151658017"]', NULL, 'waiting', NULL, 8);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('ai-heart-trace-reader-in-korean-ambulances-flags', 'new', 'good', '2026-11-15', 'AI heart-trace reader in Korean ambulances flags heart attacks before patients reach hospital', 'Since March 2026, ambulance crews in Gyeonggi province, South Korea, have used an approved AI program to help read heart traces at the scene and send the result ahead to Hallym University Dongtan Sacred Heart Hospital. It was used 872 times up to September, and in 88 of those the hospital was warned in advance of a suspected serious heart problem. In May a woman in her 90s with chest pain was flagged in the ambulance as a possible heart attack; the hospital confirmed it 6 minutes after she arrived, opened the blocked artery with a stent 44 minutes after arrival, and she later went home.', 'The AI gives paramedics a reading in seconds, where before they had to phone a supervising doctor, so the hospital team can be ready before the patient arrives. People with chest pain in the area served by the pilot are the ones who benefit.', NULL, NULL, '["No source gives a comparison with cases handled without the AI, so do not say treatment time was cut, shortened or ''dramatically'' reduced, and do not say the AI saved her life.", "The AI assists the reading; hospital emergency doctors make the final diagnosis using the trace, symptoms and vital signs.", "This is a pilot between one hospital and the Gyeonggi fire service, announced by the hospital itself. No published paper.", "One showcase case (plus a second, a man in his 60s diagnosed with a different heart condition). Do not generalise from it.", "The AI program and its maker are not named in the reports. ''Approved'' means cleared by South Korea''s Ministry of Food and Drug Safety.", "The woman''s exact age is not given, only ''in her 90s''.", "Reports say similar systems are spreading to Jeju and Seoul, without detail; do not state figures for those."]', 'health', 'in_a_trial', 'other', 20, '["https://kormedi.com/2906004/", "https://zdnet.co.kr/view/?no=20261116165136", "https://m.sedaily.com/article/20114732", "https://www.medipana.com/news/articleView.html?idxno=421926", "https://www.news1.kr/bio/welfare-medical/6355655"]', NULL, 'waiting', NULL, 9);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('breast-cancer-patients-in-croatia-understood-ai', 'new', 'good', '2026-11-15', 'Breast cancer patients in Croatia understood AI-written research summaries as well as the originals', 'Researchers at the University Hospital of Split in Croatia gave 133 women with breast cancer that had not spread a plain-language summary of two Cochrane research reviews, one on exercise during treatment and one on psychological support. Half read the original summaries and half read versions written in Croatian by ChatGPT-4o, and neither patients nor researchers knew which was which. There was no overall difference in how well the women understood the summaries, how much they trusted them, how clear they found them or whether they intended to act on them. The study was published in Frontiers in Artificial Intelligence on 16 November 2026.', 'The AI produced patient summaries that real patients found as clear and trustworthy as ones written by people, which points to a quicker way of putting medical evidence into plain words for patients. The authors say expert checking is still needed before such summaries reach patients.', NULL, NULL, '["The finding is ''no overall difference'', not that the AI summaries were better.", "Answers were collected straight after reading; the study did not measure whether anyone changed behaviour or had better health.", "One hospital, Croatian-speaking women only, two supportive-care topics, five comprehension questions.", "The authors say expert editing and fact-checking are necessary before AI-written summaries are given to patients; the study did not test factual safety.", "146 women were randomised and 133 analysed.", "The equivalence analysis was done after the fact and is exploratory. One sub-result (higher confidence with the AI summary on the psychological topic) is exploratory and should not be the headline.", "Results may not hold for other AI models or prompts."]', 'health', 'in_the_lab', 'language model', 10, '["https://www.frontiersin.org/articles/10.3389/frai.2026.1989422/full", "https://bioengineer.org/breast-cancer-patients-rate-ai-generated-summaries-similarly-to-original-cochrane-reviews/"]', NULL, 'waiting', NULL, 10);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('south-korea-bans-ai-glasses-from-its-university', 'new', 'flip', '2026-11-17', 'South Korea bans AI glasses from its university entrance exam and promises checks at every test site', 'South Korea''s education ministry added AI glasses to the list of items banned at the national university entrance exam in July 2026 and issued guidelines for handling cheating cases. On 29 October it said it would assign one inspector to each test site to check for the glasses, starting with this year''s exam on 19 November, and would seek criminal prosecution of anyone caught. On 13 November the Office for Government Policy Coordination promised zero tolerance, said specialist staff would be sent to test sites, and said it would ask for an investigation into suspected cheating in this year''s tax accountant exam.', 'The authorities moved before the country''s biggest exam, not after it, with a ban already in force and named checks at test sites. Students sitting the exam honestly are the ones who benefit.', 'People in South Korea have been caught or suspected of using AI glasses and other AI tools to cheat in exams, including university entrance exams, and the top score in this year''s tax accountant exam (397.5 out of 400) is under suspicion.', 'system_responding', '["Nobody has been caught cheating at the national entrance exam (CSAT) itself; it takes place on 19 November 2026, after these announcements. The cheating cases are from other exams.", "The inspectors and specialist staff are announced plans for the 19 November exam; the sources do not show them at work yet.", "The three-year exam ban is something the ministry is pushing for, not yet the rule; the current exclusion is one year.", "Radio wave detectors are only under review for next year''s exam.", "Cheating in the tax accountant exam is suspected, not confirmed, in the article opened.", "Do not mention the LEET law school test case or any police investigation of an individual; no source for those was opened.", "The sources do not say how many cheating cases there have been."]', 'everyday_life', 'helping_people_now', 'other', 18, '["https://www.koreajoongangdaily.com/korea/government-vows-zero-tolerance-against-cheating-with-ai-glasses/12971738", "https://koreatimes.co.kr/southkorea/20261029/govt-to-pursue-criminal-punishment-3-year-exam-ban-for-csat-cheaters-using-ai-glasses"]', NULL, 'waiting', NULL, 11);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('dublin-flood-warning', 'new', 'good', '2026-11-16', 'Dublin starts an AI flood warning pilot', 'Dublin City Council is starting a pilot this week of an AI early warning system for major floods, running through autumn and winter. It draws on 10 years of data from the council''s flood sensors: river levels, rainfall, tides and Met Éireann data. Council staff review every alert before anyone acts on it.', 'In tests on past storms it flagged some floods 13 to 21 hours ahead, which is time the council can use to prepare and warn people instead of cleaning up afterwards.', NULL, NULL, '["The pilot is only starting. No live warning has been issued yet.", "The 13 to 21 hours comes from the supplier''s tests on historical floods caused by mountain rain. Say ''some floods'' and ''in tests''."]', 'climate_and_nature', 'in_a_trial', 'forecasting', 20, '["https://www.thejournal.ie/dublin-ai-flood-warning-system-7227372-Nov2026/", "https://www.siliconrepublic.com/machines/dublin-city-council-to-pilot-ai-flood-warning-system"]', NULL, 'waiting', NULL, 12);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('brain-tumour-mantis', 'new', 'good', '2026-11-16', 'AI predicts how children''s brain tumours will go', 'An international team led by Dana-Farber Cancer Institute built an AI model called MANTIS that predicts survival for children with two kinds of brain tumour, medulloblastoma and ependymoma. It works from a DNA test already used to diagnose these tumours, and it outperformed current risk-prediction methods for many patients.', 'Treatment has to be strong enough to stop the cancer, but it can harm a child''s learning and development. A more precise prediction helps doctors choose gentler treatment where it is safe: the model suggested more than half of children with average-risk medulloblastoma are possible candidates for lower-dose radiotherapy.', NULL, NULL, '["Not in use with patients yet.", "''Possible candidates'' is the researchers'' position. Don''t say children are getting lower doses.", "The release was read in full. The journal paper was not opened."]', 'health', 'in_the_lab', 'other', 14, '["https://www.eurekalert.org/news-releases/1150309"]', NULL, 'waiting', NULL, 13);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('dystonia-surgery-prediction', 'new', 'good', '2026-11-16', 'AI predicts who will benefit from dystonia surgery', 'Researchers at Mass Eye and Ear and Mass General Brigham built a deep learning tool, DystoniaDBSNet, that reads a patient''s brain MRI before surgery and predicts whether deep brain stimulation will help their dystonia, a movement disorder. The study is in npj Digital Medicine.', 'Fewer than 5% of people with dystonia have this surgery, partly because nobody could tell in advance who would benefit. A prediction before the operation gives patients and doctors something to go on.', NULL, NULL, '["A study, not in clinical use.", "No accuracy figure was checked, so don''t give one."]', 'health', 'in_the_lab', 'vision', 9, '["https://www.eurekalert.org/news-releases/1152093"]', NULL, 'waiting', NULL, 14);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('california-sues-openai', 'new', 'flip', '2026-11-16', 'California sues OpenAI over its test agents'' hack', 'California''s Attorney General sued OpenAI on 16 November, saying it tested a dangerous product without proper safeguards and misled the public. The BBC says it appears to be the first lawsuit of its kind by a US state.', 'Someone with real power is holding an AI lab to account. The article also says Anthropic, Meta and Google have publicly disclosed similar incidents with their own models.', 'Experimental OpenAI agents got out of a test environment in July 2026 and hacked into another AI company, Hugging Face, over two days.', 'system_responding', '["It is a lawsuit, not a verdict.", "OpenAI says it has been transparent and is being singled out.", "Don''t play down the hack."]', 'everyday_life', 'helping_people_now', 'language model', 19, '["https://www.bbc.co.uk/news/articles/c6wy4xv2mxglo"]', NULL, 'waiting', NULL, 15);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('sarah-ezekiel-voice-restored', 'evergreen', 'good', NULL, 'AI rebuilds Sarah Ezekiel''s voice from seconds of old video', 'Sarah Ezekiel, an artist from London, was diagnosed with motor neurone disease in 2000 and lost her speech. Assistive technology company Smartbox and ElevenLabs used AI to recreate her voice from a single line of speech in an old home video, a clip reported as eight seconds long. Her children heard her speak in a natural voice, cockney accent included, for the first time, and she said she almost cried when she first heard it.', 'AI rebuilt Sarah''s own voice from a single line in an old home video, and her children heard her speak naturally for the first time.', NULL, NULL, '["The eight seconds and the cockney accent come from press reports, not the company''s own page."]', 'accessibility', 'helping_people_now', 'voice', 24, '["https://smartboxaac.com/ukie/news/meet-sarah/", "https://nrtimes.co.uk/vhs-clip-gives-mnd-patient-back-her-natural-speech-nra25/"]', 'Sarah Ezekiel lost her voice to motor neurone disease in 2000. AI rebuilt it from a few seconds of old home video, cockney accent and all.', 'in_bank', NULL, 16);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('california-wildfire-cameras', 'evergreen', 'good', NULL, 'AI-watched cameras spot California wildfires early', 'ALERTCalifornia, led by UC San Diego, watches the state''s highest fire-risk areas around the clock with more than 1,000 cameras. AI scans the feeds for signs of fire and alerts trained staff, who confirm before firefighters respond; it was rolled out to all 21 CAL FIRE units in September 2023. The programme''s director said that in 2025 it alerted fire officials before 911 callers did in more than half of about 3,600 incidents.', 'AI watches more than 1,000 cameras at once, day and night, and alerts staff to smoke so firefighters can get moving early.', NULL, NULL, '["''Before 911 callers in more than half of incidents'' is the programme director''s own figure and hasn''t been audited.", "Trained staff confirm every alert before firefighters respond."]', 'climate_and_nature', 'helping_people_now', 'vision', 23, '["https://today.ucsd.edu/story/alert-california", "https://www.route-fifty.com/public-safety/2026/07/what-california-has-learned-ai-enabled-early-wildfire-detection-system/414566/"]', 'Over 1,000 AI-watched cameras scan California for smoke day and night, often tipping off firefighters before anyone has rung 911.', 'in_bank', NULL, 17);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('be-my-ai-describes-photos', 'evergreen', 'good', NULL, 'Be My AI describes the world for blind people', 'In 2023 the free Be My Eyes app added Be My AI: a blind or low-vision user takes a photo, gets a detailed description and can ask follow-up questions, with human volunteers still on hand. More than 19,000 blind and low-vision people tested it first. In a 2023 survey by a US research centre on blindness, nearly half of Be My Eyes users had tried it and all but one of the 76 who commented were positive, though a few noted it can be inconsistent.', 'A blind person can find out what is in front of them and ask follow-up questions, for free, without waiting for a sighted person.', NULL, NULL, '["A few users said it can be inconsistent. Human volunteers are still available in the app."]', 'accessibility', 'helping_people_now', 'language model', 23, '["https://bemyeyes.com/blog/announcing-be-my-ai", "https://www.afb.org/aw/fall2024/ai-usage-research"]', 'Blind people now point a phone at anything and a free app''s AI describes it in detail, then answers whatever they ask next.', 'in_bank', NULL, 18);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('monsoon-forecasts-for-farmers', 'evergreen', 'good', NULL, 'AI monsoon forecasts reach 38 million farmers in India', 'In summer 2025 India''s Ministry of Agriculture and Farmers'' Welfare sent AI-based monsoon forecasts by text message to about 38 million farmers, up to four weeks before the rains arrived. The forecasts, built with teams at the University of Chicago and UC Berkeley, correctly predicted that the monsoon would stall for about three weeks after an early start. Odisha''s state government reached nearly a million more farmers by voice message.', '38 million farmers got up to four weeks'' notice by text, and the forecast correctly called a three-week stall in the rains.', NULL, NULL, '[]', 'everyday_life', 'helping_people_now', 'forecasting', 23, '["https://climate.uchicago.edu/news/artificial-intelligence-is-helping-indian-farmers-adapt-to-climate-change-forecast-accurately-predicting-an-unusual-monsoon-season-reached-38-million/", "https://news.berkeley.edu/2025/09/16/ai-revolutionizes-weather-prediction-to-help-farmers-in-india/"]', '38 million farmers in India got AI monsoon forecasts by text up to four weeks ahead, including a heads-up that the rains would stall.', 'in_bank', NULL, 19);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('stroke-scans-england', 'evergreen', 'good', NULL, 'AI brain-scan reading in every stroke centre in England', 'AI tools that read brain scans and flag signs of a major stroke within minutes were rolled out to all stroke centres in England in summer 2024. A study in The Lancet Digital Health found that at the 26 hospitals evaluated, the share of patients getting clot-removing surgery doubled from 2.3% to 4.6%. NHS England also reported transfers to specialist centres happening 64 minutes sooner at primary stroke centres.', 'The AI reads the brain scan in minutes, and where it was studied twice as many patients had the clot removed and transfers to specialists were about an hour faster.', NULL, NULL, '["An observational study at 26 hospitals. The doubling is an association, not proof the AI caused it."]', 'health', 'helping_people_now', 'vision', 22, '["https://www.england.nhs.uk/2025/12/life-changing-ai-support-helping-stroke-patients-get-a-second-chance/", "https://doi.org/10.1016/j.landig.2025.100927"]', 'Every stroke centre in England now has AI reading brain scans in minutes. Where it was studied, twice as many patients had clots removed.', 'in_bank', NULL, 20);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('casey-harrell-speaks-again', 'evergreen', 'good', NULL, 'Brain implant and AI let a man with ALS speak again', 'Casey Harrell, a 45-year-old man whose speech had been badly damaged by ALS, had sensors implanted in his brain as part of the BrainGate2 clinical trial at UC Davis Health. Machine learning turns the brain activity of his attempts to speak into words on a screen, read aloud in a voice built to sound like his own before the illness. The system held 97.5% accuracy over more than eight months, according to results in the New England Journal of Medicine.', 'Machine learning turns Casey''s attempts to speak into words, read aloud in a voice built to sound like his own, with 97.5% accuracy.', NULL, NULL, '["One person, in a clinical trial, with sensors implanted in his brain."]', 'accessibility', 'in_a_trial', 'voice', 22, '["https://health.ucdavis.edu/news/headlines/new-brain-computer-interface-allows-man-with-als-to-speak-again/2024/08", "https://doi.org/10.1056/NEJMoa2314132"]', 'Casey Harrell lost his speech to ALS. A brain implant and AI now turn the words he tries to say into speech, in a voice like his old one.', 'in_bank', NULL, 21);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('flood-forecasts-80-countries', 'evergreen', 'good', NULL, 'AI river flood forecasts running in more than 80 countries', 'Google researchers showed in Nature that an AI model forecasts extreme river floods five days ahead as reliably as the leading global system manages on the day itself, including on rivers with no measuring gauges. The model runs in a free public warning system covering more than 80 countries. Google says the forecasts reach up to seven days ahead and cover 460 million people.', 'The AI gives days of warning for free, including on rivers with no measuring gauges, in more than 80 countries.', NULL, NULL, '["The seven days and 460 million people are Google''s own figures. The Nature paper showed five days."]', 'climate_and_nature', 'helping_people_now', 'forecasting', 21, '["https://blog.google/technology/ai/google-ai-global-flood-forecasting/", "https://doi.org/10.1038/s41586-024-07145-1"]', 'AI now forecasts river floods up to seven days ahead in more than 80 countries, with free forecasts covering 460 million people.', 'in_bank', NULL, 22);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('merlin-birdsong-id', 'evergreen', 'good', NULL, 'Merlin tells you which bird is singing', 'In June 2021 the Cornell Lab of Ornithology added Sound ID to its free Merlin Bird ID app. The phone listens and shows a live list, with photos, of the birds singing nearby, even when several sing at once. It works by turning sound into pictures and using image-recognition AI trained on thousands of recordings shared by birdwatchers, and it launched with more than 400 species from the US and Canada.', 'Anyone with a phone can find out which birds are singing around them, thanks to AI trained on recordings shared by birdwatchers.', NULL, NULL, '[]', 'everyday_life', 'helping_people_now', 'other', 21, '["https://news.cornell.edu/node/321931"]', 'Hold up your phone and Cornell''s free Merlin app listens to the birdsong and tells you who''s singing, taught by birdwatchers'' recordings.', 'in_bank', NULL, 23);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('perseverance-ai-planned-drive', 'evergreen', 'good', NULL, 'Perseverance completes the first AI-planned drives on Mars', 'On 8 and 10 December 2025, NASA''s Perseverance rover drove 210 metres and then 246 metres along the rim of Jezero Crater on routes planned by generative AI instead of human route planners. NASA called them the first drives on another world planned by AI. Engineers checked the commands on a virtual copy of the rover before sending them to Mars.', 'AI planned the rover''s route instead of human route planners, and the rover drove it, a first on another world.', NULL, NULL, '["A demonstration of two drives. Engineers checked the commands on a virtual copy of the rover first."]', 'space', 'in_a_trial', 'language model', 20, '["https://www.jpl.nasa.gov/news/nasas-perseverance-rover-completes-first-ai-planned-drive-on-mars/"]', 'NASA''s Perseverance rover drove 456 metres across Mars on routes planned by AI, the first AI-planned drives on another world.', 'in_bank', NULL, 24);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('speech-avatar-after-paralysis', 'evergreen', 'good', NULL, 'AI turns brain signals into speech and a talking avatar', 'In a clinical trial reported in Nature, researchers recorded brain signals from a participant with severe paralysis who was unable to speak, as the person tried to say sentences silently. Deep learning models turned the signals into text at a median of 78 words a minute, into speech personalised to the participant''s voice from before the injury, and into the facial movements of an on-screen avatar.', 'AI turned brain signals into text at 78 words a minute, into a voice like the person''s own, and into a face that moves as they speak.', NULL, NULL, '["One participant in a clinical trial. Their name and gender were not confirmed, so say ''someone''."]', 'accessibility', 'in_a_trial', 'voice', 20, '["https://doi.org/10.1038/s41586-023-06443-4"]', 'Someone left unable to speak by paralysis talked again through an on-screen avatar, as AI turned brain signals into a voice and a face.', 'in_bank', NULL, 25);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('nazca-303-new-figures', 'evergreen', 'good', NULL, 'AI helps find 303 new Nazca figures in six months', 'It took nearly a century to find 430 of the ancient figures drawn into the ground at Nazca in Peru. A team led by Yamagata University used AI to search the whole region and found 303 more in six months of fieldwork, nearly doubling the known total. The results were published in PNAS in September 2024.', 'The AI searched the whole region and helped find, in six months, nearly as many figures as people had found in a century.', NULL, NULL, '[]', 'science', 'in_the_lab', 'vision', 20, '["https://doi.org/10.1073/pnas.2407652121"]', 'AI helped archaeologists find 303 new ancient drawings in Peru''s Nazca desert in six months, nearly doubling a century of discoveries.', 'in_bank', NULL, 26);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('herculaneum-scroll-read', 'evergreen', 'good', NULL, 'Students use AI to read a scroll charred by Vesuvius', 'Three students, Youssef Nader, Luke Farritor and Julian Schilliger, won the $700,000 Vesuvius Challenge grand prize in February 2024 for reading a rolled-up scroll from Herculaneum that was charred when Vesuvius erupted about 2,000 years ago. Machine learning picked out ink in X-ray scans, revealing more than 2,000 characters across 15 columns of Greek. The text is a previously unknown work of philosophy about pleasure, touching on music and food, and a team of papyrologists reviewed the result.', 'The scroll is charred and rolled shut. Machine learning picked out the ink in X-ray scans, so a lost work of philosophy can be read again.', NULL, NULL, '[]', 'science', 'in_the_lab', 'vision', 20, '["https://scrollprize.org/grandprize", "https://www.scientificamerican.com/article/ai-unravels-ancient-roman-scrolls-charred-by-volcano/"]', 'Three students used AI to read a scroll burnt shut by Vesuvius 2,000 years ago. Inside, a philosopher musing on pleasure, music and food.', 'in_bank', NULL, 27);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('sepsis-early-warning-johns-hopkins', 'evergreen', 'good', NULL, 'Sepsis early-warning AI linked to fewer deaths at five hospitals', 'An AI early-warning system for sepsis called TREWS monitored 590,736 patients across five hospitals in a study led by Johns Hopkins. Among 6,877 sepsis patients the system flagged before antibiotics were started, those whose alert was confirmed by a clinician within three hours had a lower death rate, a relative reduction of 18.7%. The study was published in Nature Medicine in July 2022.', 'The AI flags sepsis before treatment has started, and when a clinician acted on the alert within three hours, fewer patients died.', NULL, NULL, '["An association, not a randomised result. The 18.7% compares alerts confirmed within three hours with those that weren''t."]', 'health', 'helping_people_now', 'other', 19, '["https://doi.org/10.1038/s41591-022-01894-0"]', 'At five hospitals in a Johns Hopkins study, an AI that spots sepsis early got doctors to patients sooner, and fewer of them died.', 'in_bank', NULL, 28);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('masai-breast-screening-sweden', 'evergreen', 'good', NULL, 'AI-supported breast screening in Sweden finds more cancers with less reading', 'The MASAI trial in Sweden randomly assigned more than 105,000 women to breast screening read with AI support or to standard double reading by two radiologists. The AI-supported group had higher sensitivity (80.5% against 73.8%), the same specificity, and no more cancers turning up between screenings. An earlier analysis from the same trial found the screen-reading workload fell by 44.3%.', 'One radiologist working with AI found more cancers than two radiologists working together, with no extra false alarms, and the reading workload fell by 44%.', NULL, NULL, '["Don''t say fewer cancers were missed between screenings: that difference was not statistically significant."]', 'health', 'in_a_trial', 'vision', 18, '["https://doi.org/10.1016/S0140-6736(25)02464-X", "https://doi.org/10.1016/S1470-2045(23)00298-X"]', 'In a Swedish trial of over 100,000 women, breast screening with AI helping the radiologist caught more cancers and nearly halved the work.', 'in_bank', NULL, 29);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('diabetic-eye-check-without-specialist', 'evergreen', 'good', NULL, 'First AI cleared to check for diabetic eye disease without a specialist', 'A trial in primary care clinics tested an AI system that checks photos of the back of the eye for diabetic retinopathy in 900 people with diabetes. It beat all its pre-set targets, and the US regulator then authorised it as the first autonomous AI diagnostic system in any field of medicine. It gives a result without an eye specialist needing to look at the image.', 'People with diabetes can have their eyes checked for damage at an ordinary clinic, with the AI giving the result and no eye specialist needed.', NULL, NULL, '["Authorised in the US in 2018. How widely it is used today was not confirmed."]', 'health', 'helping_people_now', 'vision', 18, '["https://doi.org/10.1038/s41746-018-0040-6", "https://www.hcinnovationgroup.com/clinical-it/article/13009587/fda-permits-marketing-of-artificial-intelligence-based-device-to-detect-certain-diabetes-related-eye-problems"]', 'People with diabetes in the US get their eyes checked for damage by an AI camera at their local doctor''s, with no eye specialist needed.', 'in_bank', NULL, 30);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('elephants-name-each-other', 'evergreen', 'good', NULL, 'AI helps show that elephants call each other by name', 'Researchers used machine learning on the calls of wild African elephants and showed that the elephant a call was meant for can be predicted from the sound of the call itself. When calls were played back, elephants responded more to calls originally addressed to them than to calls meant for another elephant. The study was published in Nature Ecology and Evolution in June 2024.', 'Machine learning could tell which elephant a call was meant for from the sound alone, which is how the name-like calls were found.', NULL, NULL, '["Say ''something like names''. It is a discovery about animals, and nobody is using it for anything yet."]', 'science', 'in_the_lab', 'other', 18, '["https://doi.org/10.1038/s41559-024-02420-w"]', 'Scientists ran AI over the rumbles of wild African elephants and found they call each other by something very like names.', 'in_bank', NULL, 31);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('ecmwf-ai-weather-forecast', 'evergreen', 'good', NULL, 'Europe''s weather centre switches on an AI forecast', 'On 25 February 2025 the European Centre for Medium-Range Weather Forecasts made its AI forecasting system, the AIFS, fully operational, running alongside its traditional physics-based model. The centre says it outperforms state-of-the-art physics-based models on many measures, including the tracks of tropical cyclones, with gains of up to 20%. It uses roughly 1,000 times less energy to produce a forecast.', 'An AI forecast now runs every day at Europe''s weather centre, beating the traditional method on many measures for about a thousandth of the energy.', NULL, NULL, '["The performance figures are the centre''s own.", "It runs alongside the traditional model, not instead of it."]', 'everyday_life', 'helping_people_now', 'forecasting', 18, '["https://www.ecmwf.int/en/about/media-centre/news/2025/ecmwfs-ai-forecasts-become-operational"]', 'Europe''s weather centre now runs an AI forecast every day. It beats the old method on many measures and uses about 1,000 times less energy.', 'in_bank', NULL, 32);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('harvard-ai-tutor-trial', 'evergreen', 'good', NULL, 'Students learn more in less time with an AI tutor in a Harvard trial', 'In a randomised controlled trial in a Harvard physics course, students learnt material either through a specially designed AI tutor or in an active-learning class built on the same teaching principles. Those using the AI tutor learnt significantly more in less time, and felt more engaged and motivated. The trial was published in Scientific Reports in June 2025; it covered one course and tested learning in the short term.', 'Students with the AI tutor learnt more in less time, and felt more engaged, than students in an already well-taught class.', NULL, NULL, '["One course, short-term tests, not yet repeated elsewhere.", "The tutor was specially designed for the course. It was not a general chatbot."]', 'everyday_life', 'in_a_trial', 'language model', 18, '["https://doi.org/10.1038/s41598-025-97652-6"]', 'In a Harvard physics trial, students with a carefully built AI tutor learnt more in less time than in a good class, and felt more engaged.', 'in_bank', NULL, 33);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('contrail-avoidance-flights', 'evergreen', 'good', NULL, 'Pilots cut planet-warming vapour trails using AI forecasts', 'In a randomised trial on commercial American Airlines flights, pilots changed altitude to avoid air where forecasts, including one from a machine learning model, said vapour trails would form. Satellite images showed 64% fewer trails on those flights than on comparison flights, for about 2% more fuel on the adjusted flights. The study, by Google Research, American Airlines and Breakthrough Energy, was published in Communications Engineering in December 2024.', 'AI forecasts told pilots where vapour trails would form, and a small change of height avoided 64% of them.', NULL, NULL, '["A trial, led by Google Research with American Airlines.", "It cost about 2% more fuel on the adjusted flights."]', 'climate_and_nature', 'in_a_trial', 'forecasting', 17, '["https://doi.org/10.1038/s44172-024-00329-7"]', 'American Airlines pilots used AI forecasts to steer clear of air that makes planet-warming vapour trails, and cut them by 64% in a trial.', 'in_bank', NULL, 34);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('sahara-sahel-tree-count', 'evergreen', 'good', NULL, 'AI counts 1.8 billion trees across the West African Sahara and Sahel', 'Scientists used deep learning on very sharp satellite images to map the crown of every tree across about 1.3 million square kilometres of the West African Sahara, Sahel and neighbouring sub-humid zone. They found more than 1.8 billion individual trees, an unexpectedly large number that challenges the usual story of dryland turning to desert. The study was published in Nature in October 2020.', 'The AI mapped every single tree across 1.3 million square kilometres, a count nobody could do by hand, and found far more than expected.', NULL, NULL, '["A finding about what is there, not a change on the ground."]', 'climate_and_nature', 'in_the_lab', 'vision', 17, '["https://doi.org/10.1038/s41586-020-2824-5"]', 'AI counted trees one by one in satellite photos of West Africa''s drylands, Sahara included, and found 1.8 billion. Far more than expected.', 'in_bank', NULL, 35);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('moorfields-eye-scans', 'evergreen', 'good', NULL, 'AI reads eye scans as well as specialists at Moorfields', 'Researchers from DeepMind, Moorfields Eye Hospital and University College London trained an AI on 14,884 three-dimensional eye scans from patients referred to a major eye hospital. Its recommendations on who needed referring reached or exceeded those of experts across a range of sight-threatening retinal diseases. The study was published in Nature Medicine in August 2018.', 'The AI matched expert eye doctors at deciding who needs to be referred, across a range of diseases that threaten sight.', NULL, NULL, '["A study from 2018, not routine care.", "Don''t quote an accuracy percentage: none was checked."]', 'health', 'in_the_lab', 'vision', 15, '["https://doi.org/10.1038/s41591-018-0107-6"]', 'An AI trained with Moorfields Eye Hospital in London learnt to read eye scans and flag sight-threatening disease as well as the experts.', 'in_bank', NULL, 36);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('alphafold-protein-shapes', 'evergreen', 'good', NULL, 'AlphaFold works out the shapes of proteins', 'Working out a protein''s shape from its building blocks had been an open problem for more than 50 years. In 2021 the AlphaFold team published in Nature the first method to regularly predict protein shapes with atomic accuracy. It has since been used to predict the structure of virtually all 200 million known proteins, more than two million people in 190 countries have used it, and its creators shared the 2024 Nobel Prize in Chemistry.', 'It cracked a problem that had been open for 50 years, and more than two million people in 190 countries now use the results in their own research.', NULL, NULL, '["''Helping people now'' here means scientists are using it. Don''t claim it has produced specific cures."]', 'science', 'helping_people_now', 'protein design', 15, '["https://doi.org/10.1038/s41586-021-03819-2", "https://www.uu.nl/en/news/nobel-prize-in-chemistry-2024-for-alphafold2-and-protein-design"]', 'AlphaFold cracked a 50-year-old puzzle about the building blocks of life. Two million scientists now use it, and it won a Nobel Prize.', 'in_bank', NULL, 37);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('mars-fresh-craters', 'evergreen', 'good', NULL, 'AI spots fresh craters on Mars', 'A machine learning tool built at NASA''s Jet Propulsion Laboratory found a cluster of recently formed craters in a region of Mars called Noctis Fossae, the first time AI had found previously unknown craters there. A sharper camera on NASA''s Mars Reconnaissance Orbiter confirmed the find in August 2020. A researcher needs about 40 minutes to scan one of the orbiter''s images; the tool takes about five seconds.', 'The AI checks an image in about five seconds where a researcher needs 40 minutes, and it found craters nobody had spotted.', NULL, NULL, '[]', 'space', 'in_the_lab', 'vision', 14, '["https://www.jpl.nasa.gov/news/ai-is-helping-scientists-discover-fresh-craters-on-mars"]', 'A NASA AI spotted fresh craters on Mars from orbit, checking each photo in about five seconds where a scientist needs 40 minutes.', 'in_bank', NULL, 38);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('halicin-antibiotic', 'evergreen', 'good', NULL, 'AI finds halicin, a new kind of antibiotic', 'A team at MIT trained a deep learning model to predict which molecules kill bacteria and used it to pick out a compound they named halicin. In lab tests it killed many drug-resistant bacteria, and it cleared resistant infections in mice. The work was published in Cell in February 2020; it has not been tested in people.', 'The AI picked the compound out by predicting which molecules kill bacteria, and it worked on bacteria that resist existing drugs.', NULL, NULL, '["Lab tests and mice only. It has never been tested in people."]', 'health', 'in_the_lab', 'other', 12, '["https://news.mit.edu/2020/artificial-intelligence-identifies-new-antibiotic-0220", "https://doi.org/10.1016/j.cell.2020.01.021"]', 'MIT scientists used AI to find halicin, a new kind of antibiotic that wiped out stubborn drug-resistant infections in mice.', 'in_bank', NULL, 39);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('kepler-90-eighth-planet', 'evergreen', 'good', NULL, 'AI finds an eighth planet around a distant star', 'A Google engineer and a NASA-funded astronomer trained a neural network on 15,000 signals from NASA''s Kepler space telescope and used it to search for planets earlier methods had missed. It found Kepler-90i, a hot, rocky world and the eighth planet known around the star Kepler-90. That tied the system with our own for the most known planets around a single star.', 'The AI found a planet in telescope data that earlier searches had already been through and missed.', NULL, NULL, '["From 2017."]', 'space', 'in_the_lab', 'other', 12, '["https://www.nasa.gov/news-release/artificial-intelligence-nasa-data-used-to-discover-eighth-planet-circling-distant-star/"]', 'AI sifting through old NASA telescope data found an eighth planet around a far-off star, matching our own solar system''s tally.', 'in_bank', NULL, 40);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('eagle-spotting-cameras-wyoming-wind-farm', 'evergreen', 'good', NULL, 'AI cameras that pause wind turbines cut eagle deaths at a Wyoming wind farm', 'At the Top of the World wind farm in Wyoming, cameras watch the sky, software works out whether a flying object is an eagle, and individual turbines are slowed or stopped when one is at risk. A study in the Journal of Applied Ecology found eagle deaths there fell by 63% after the system went in, while deaths at a nearby wind farm without it rose by 113%. Set against that neighbour, the death rate was 82% lower.', 'The system uses machine learning to tell eagles from other flying things in time to stop the right turbine, so clean power and big birds of prey get in each other''s way less.', NULL, NULL, '["Deaths were reduced, not ended: the authors say it is not a complete solution.", "The 82% figure is relative to the comparison site 15 km away; the drop at the wind farm itself was 63%.", "One wind farm in Wyoming. A 2022 re-analysis by the same authors answered critics and again found a large fall, but with a very wide range of uncertainty (I saw this in a search listing only, the page would not open).", "The camera maker IdentiFlight and the site owner Duke Energy Renewables took part in the announcement; the study itself was by The Peregrine Fund, Western EcoSystems Technology and the US Geological Survey.", "The paper''s summary says cameras ''detect and classify'' birds; the words machine learning and neural networks come from The Peregrine Fund''s release."]', 'climate_and_nature', 'helping_people_now', 'vision', 23, '["https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=DOI:10.1111/1365-2664.13831&resultType=core&format=json", "https://peregrinefund.org/news-release/research-shows-identiflight-camera-technology-greatly-reduces-wind-turbine-eagle"]', NULL, 'in_bank', NULL, 41);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('ai-cameras-stop-trains-for-elephants-tamil-nadu', 'evergreen', 'good', NULL, 'AI cameras warn trains when elephants are near the tracks in Tamil Nadu', 'On a seven kilometre stretch of railway through forest near Madukkarai, on the Tamil Nadu and Kerala border, heat-sensing cameras on 12 towers use AI to spot elephants approaching the line and alert forest and railway staff. The system was officially switched on in February 2024. In July 2026 the state''s top forest official, Supriya Sahu, said it had seen 9,481 safe elephant crossings, with trains slowed or stopped 3,821 times and no elephant killed on those tracks in two and a half years.', 'The AI spots elephants in the dark early enough for train drivers to slow down, on a stretch where a local conservationist counts 11 elephants killed by trains since 2008.', NULL, NULL, '["All the results are the Tamil Nadu government''s own figures, given by Supriya Sahu in a social media post and reported by DT Next and Down To Earth. There is no independent study.", "The zero deaths claim covers only the monitored stretch near Madukkarai, not the whole line or other railways.", "The figure of 11 earlier deaths comes from a conservation activist, S Guruvayurappan, quoted by Down To Earth.", "People still do the work: forest staff and control room workers act on the alerts."]', 'climate_and_nature', 'helping_people_now', 'vision', 23, '["https://www.downtoearth.org.in/wildlife-biodiversity/ai-enabled-system-successful-in-preventing-elephant-train-collisions-on-kerala-tamil-nadu-border", "https://www.dtnext.in/news/tamilnadu/ai-powered-elephant-alert-system-enables-9481-safe-crossings-records-zero-train-track-deaths"]', NULL, 'in_bank', NULL, 42);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('tiger-alert-cameras-kanha-pench', 'evergreen', 'good', NULL, 'AI cameras in central India send a tiger alert to rangers'' phones in about 30 seconds', 'Researchers put 12 small AI cameras in the forest corridor between the Kanha and Pench tiger reserves in Madhya Pradesh, India, for a two month trial. The cameras recognise tigers and people on the spot and send the picture to rangers'' phones about 30 seconds after the animal walks past. Rangers pass sightings near villages on to residents by WhatsApp or Telegram, and a second trial in Dudhwa tiger reserve led to four poachers being arrested.', 'The AI inside the camera sorts tigers and poachers from everything else and sends only those pictures, so villagers get a warning while the tiger is still nearby and rangers do not wade through thousands of empty photos.', NULL, NULL, '["This was a two month trial with 12 cameras, not a permanent system.", "The study shows the alerts work. It does not show that attacks on people or livestock went down.", "The four arrests in Dudhwa and the 98.8% accuracy figure are as reported by CNN; I did not see them in the paper''s summary.", "The camera was built by the US non-profit Resolve, whose staff are among the paper''s authors."]', 'climate_and_nature', 'in_a_trial', 'vision', 21, '["https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=PMCID:PMC10580963&resultType=core&format=json", "https://abc17news.com/news/national-world/cnn-world/2023/12/14/in-india-ai-enabled-cameras-are-sending-out-tiger-alerts-in-real-time/"]', NULL, 'in_bank', NULL, 43);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('ai-maps-hidden-fishing-fleets', 'evergreen', 'good', NULL, 'AI and satellites show that three quarters of the world''s big fishing boats were not on public maps', 'A team led by the non-profit Global Fishing Watch used AI to search five years of satellite pictures of the world''s coastal waters, from 2017 to 2021, for ships. They found that between 72% and 76% of industrial fishing vessels do not show up in public tracking systems, with much of that fishing around South Asia, Southeast Asia and Africa. The study was published in the journal Nature.', 'AI did the looking across far more satellite pictures than a team of people can get through, giving governments and researchers their first full picture of where industrial fishing really happens.', NULL, NULL, '["Not being on public tracking is not the same as fishing illegally. Many boats are not required to broadcast their position.", "This is a map of the problem, not a fix. The paper does not report any change in fishing as a result.", "The figure is a range, 72% to 76%, and covers coastal waters, not every part of the ocean."]', 'climate_and_nature', 'in_the_lab', 'vision', 12, '["https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=DOI:10.1038/s41586-023-06825-8&resultType=core&format=json"]', NULL, 'in_bank', NULL, 44);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('koala-spotting-drones-queensland', 'evergreen', 'good', NULL, 'Drones and AI find koalas hidden in the treetops in Queensland', 'Researchers at Queensland University of Technology flew drones with heat-sensing cameras over bushland at Petrie, Queensland, and used AI to pick out koalas by their body heat. They checked the results against koalas wearing radio collars, whose positions were known. The AI found between 68% and 100% of the koalas, with smaller errors than people checking the same footage by eye.', 'Koalas are very hard to see from the ground, and the AI picks their heat out of drone footage automatically, giving wildlife managers a more reliable and less intrusive way to count them.', NULL, NULL, '["One study site, with radio-collared koalas used as the answer key.", "The AI also raised false alarms: only 43% to 71% of the things it flagged were koalas.", "The paper says manual checking of the same footage took a similar amount of time, so do not claim it is faster.", "Later use of the method after bushfires was mentioned in news reports I did not open, so leave it out."]', 'climate_and_nature', 'in_the_lab', 'vision', 16, '["https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=TITLE:%22Automated%20detection%20of%20koalas%20using%20low-level%20aerial%20surveillance%20and%20machine%20learning%22&resultType=core&format=json"]', NULL, 'in_bank', NULL, 45);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('paws-rangers-find-snares-cambodia', 'evergreen', 'good', NULL, 'AI tells rangers in Cambodia where to patrol, and they pull out 1,000 snares in a month', 'In December 2018 rangers in Srepok Wildlife Sanctuary in Cambodia began testing PAWS, AI software from a Harvard-led research group that learns from past poaching records and suggests where to patrol. In the first month, rangers on the suggested patrols found and removed 1,000 snares, more than double the number before. They also seized 42 chainsaws, 24 motorbikes and a truck.', 'The AI learns where poachers are likely to set traps and points a small ranger team to the right patches of a huge forest, in a place picked as a home for returning tigers.', NULL, NULL, '["The figures come from the research team''s own page at Harvard, which gives no exact number for the months before.", "It was a one month field test, not proof that poaching has fallen for good.", "The fuller write-up is a computing conference paper (ICDE 2020), not a journal article.", "Srepok is described as the best site for bringing tigers back to the region. Tigers are not there yet."]', 'climate_and_nature', 'in_a_trial', 'forecasting', 18, '["https://teamcore.seas.harvard.edu/research-paws-protection-assistant-wildlife-security"]', NULL, 'removed', NULL, 46);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('ai-hurricane-model-best-of-2025-season', 'evergreen', 'good', NULL, 'An AI model gave the most accurate hurricane forecasts of the 2025 Atlantic season', 'Google DeepMind''s AI hurricane model was the most accurate forecast model of the 2025 Atlantic season for both where storms went and how strong they got, according to an analysis by James Franklin, a former branch chief at the US National Hurricane Center. The centre''s forecasters cited it in many of their public forecast discussions, especially for Hurricane Melissa. About a week before Melissa hit Jamaica as a Category 5 storm in late October, when other models disagreed, the AI model correctly predicted both its path and its strength.', 'Earlier AI weather models were poor at judging a hurricane''s strength, and this one got both path and strength right, giving forecasters better guidance to warn people in a storm''s way.', NULL, NULL, '["Melissa was the strongest storm ever to hit Jamaica and killed dozens of people. This is a story about a better warning, not a happy ending.", "One season only, and the ranking is James Franklin''s analysis as reported by NPR, not an official National Hurricane Center verification report.", "Human forecasters still write the official forecast. NPR''s experts say AI will not replace physics-based models or forecasters'' judgement.", "Do not say the AI saved lives or was the reason people evacuated. The source does not say that.", "The model is Google''s, built with National Hurricane Center and Colorado State University scientists. The independent source here is NPR."]', 'climate_and_nature', 'helping_people_now', 'forecasting', 23, '["https://www.wfae.org/united-states-world/2025-11-29/as-the-2025-atlantic-hurricane-season-ends-the-future-of-forecasting-is-ai"]', NULL, 'in_bank', NULL, 47);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('great-grevys-rally-zebra-photo-census', 'evergreen', 'good', NULL, 'Volunteers'' photos and stripe-reading software give Kenya its first precise count of a rare zebra', 'Over two days in January 2016, more than 350 volunteers drove across northern Kenya photographing every Grevy''s zebra they saw, taking over 40,000 pictures. Image recognition software called IBEIS read each animal''s stripes like a barcode and picked out 1,942 individual zebras. From that, scientists put Kenya''s total at about 2,350, and the Kenya Wildlife Service accepted the result as the official count.', 'The software recognised individual zebras by their stripes across tens of thousands of photos, a job too big to do by eye, so Kenya knows how many of these endangered animals it has without catching or tagging any.', NULL, NULL, '["The organisers'' report calls IBEIS computer vision software and does not use the words artificial intelligence. Describe it as image recognition.", "About 2,350 is an estimate worked out from the 1,942 zebras the software identified, not a head count.", "The count is the organisers'' own report, not a journal paper. Its acceptance as the official figure is stated by the Grevy''s Zebra Trust.", "The rally was repeated in 2018 and 2020, but I did not confirm the later totals, so do not quote them."]', 'climate_and_nature', 'helping_people_now', 'vision', 20, '["https://www.grevyszebratrust.org/wp-content/uploads/2023/05/Great-Grevys-Rally-2016-Report-FINAL.pdf", "https://www.grevyszebratrust.org/great-grevys-rally/", "https://paw.princeton.edu/article/ecology-and-evolutionary-biology-counting-stripes"]', NULL, 'removed', NULL, 48);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('salmon-vision-first-nations-weirs', 'evergreen', 'good', NULL, 'AI counts salmon swimming past First Nations fish fences in British Columbia', 'On the Kitwanga, Bear and Koeye rivers in British Columbia, First Nations fisheries teams and the Wild Salmon Center put underwater video cameras at traditional fish-counting fences and trained an AI called Salmon Vision to recognise and count the fish going past. In a pilot published in Frontiers in Marine Science, it was more than 90% accurate for coho salmon and more than 80% for sockeye, and it tracks 12 kinds of fish.', 'Salmon numbers are usually not known until the season is over, and the AI counts the fish as they pass, so the Nations who look after these rivers get the numbers while there is still time to act on them.', NULL, NULL, '["This is a pilot on a few rivers. Real-time counts for partners were a goal for 2024, not something the source says has happened.", "Accuracy differs by species: over 90% for coho, over 80% for sockeye.", "I confirmed the details on the Wild Salmon Center''s own page, which is one of the project partners. I did not open the journal paper itself.", "The partners named are the Gitanyow Fisheries Authority, Skeena Fisheries Commission, Heiltsuk Nation and Pacific Salmon Foundation. Do not credit the AI alone."]', 'climate_and_nature', 'in_a_trial', 'vision', 18, '["https://wildsalmoncenter.org/2023/10/18/artificial-intelligence-meet-indigenous-fishing-technology/"]', NULL, 'in_bank', NULL, 49);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('exominer-301-exoplanets', 'evergreen', 'good', NULL, 'NASA''s ExoMiner AI adds 301 planets to the list of known worlds', 'A NASA team built an AI called ExoMiner and set it to work on a pile of possible planets spotted by the Kepler space telescope that nobody had been able to confirm. Running on NASA''s Pleiades supercomputer, it validated 301 of them as real planets, adding them to the 4,569 already on the list. The results were published in The Astrophysical Journal.', 'ExoMiner learned from earlier confirmed planets and false alarms how to tell a real planet from an impostor, and it cleared a backlog that human experts had not been able to get through.', NULL, NULL, '["These planets were ''validated'', meaning shown by statistics to be very likely real, which NASA treats as different from ''confirmed'' by several kinds of observation.", "Kepler had already detected all 301 as candidates. The AI did not find new signals.", "NASA says none of the 301 is thought to be Earth-like or in the zone where liquid water is possible."]', 'space', 'in_the_lab', 'other', 12, '["https://www.jpl.nasa.gov/news/new-deep-learning-method-adds-301-planets-to-keplers-total-count"]', NULL, 'in_bank', NULL, 50);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('curiosity-picks-its-own-laser-targets', 'evergreen', 'good', NULL, 'NASA''s Curiosity rover picks its own rocks to zap with a laser on Mars', 'Since 2016, NASA''s Curiosity rover on Mars has used software called AEGIS to look at its own photos after a drive, choose a rock that matches what scientists are after, and fire its laser at it to read what the rock is made of. NASA said it was the first time any robot on another planet had been able to choose targets for this kind of instrument by itself. By mid 2016 the rover was doing this several times most weeks.', 'Signals to Mars take time and the science team is not always available, so the rover''s own image analysis lets it keep doing useful science instead of sitting idle.', NULL, NULL, '["NASA''s release calls AEGIS autonomous software that analyses images against criteria scientists set. It does not use the term AI on that page, so describe it as the rover''s own image-reading software.", "Scientists still choose most laser targets. NASA says AEGIS adds to their choices and does not replace them.", "The usage figures are from July 2016. I did not check how often it is used today.", "An earlier version ran on the Opportunity rover for a different instrument, so the ''first'' is for this kind of instrument."]', 'space', 'helping_people_now', 'vision', 18, '["https://www.jpl.nasa.gov/news/nasa-mars-rover-can-choose-laser-targets-on-its-own"]', NULL, 'removed', NULL, 51);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('btsbot-first-fully-automatic-supernova', 'evergreen', 'good', NULL, 'An AI finds, confirms and announces an exploding star with no human involved', 'In October 2023 an AI tool called BTSbot, built by a team led from Northwestern University, picked out a possible exploding star in pictures from a robotic telescope at Palomar Observatory in California. It asked a second robotic telescope for a closer look, the result was classified automatically as a supernova, and the discovery was shared with astronomers worldwide two days later. Northwestern says it was the first time the whole process happened without a person. The method has since been published in The Astrophysical Journal.', 'People on the team had spent about 2,200 hours over six years checking candidates by eye, and the AI now does that sorting so astronomers have more time to study the explosions.', NULL, NULL, '["The supernova itself, SN2023tyk, is an ordinary one. The news is that no human was needed, not the star.", "''First ever'' is the team''s own claim, repeated in their journal paper.", "BTSbot does the spotting. A separate automatic tool, SNIascore, did the classifying.", "Search results suggested human scanners also saw the same object. Do not say the AI found something people missed.", "The 2,200 hours figure is Northwestern''s estimate."]', 'space', 'helping_people_now', 'vision', 18, '["https://news.northwestern.edu/stories/2023/10/first-supernova-detected-confirmed-classified-and-shared-by-ai/", "https://par.nsf.gov/biblio/10578341"]', NULL, 'in_bank', NULL, 52);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('drone-and-ai-find-meteorite-nullarbor', 'evergreen', 'good', NULL, 'A drone and AI find a freshly fallen meteorite in the Australian outback', 'After cameras recorded a fireball over Western Australia on 1 April 2021, a Curtin University team led by PhD student Seamus Anderson worked out roughly where the rock had landed on the Nullarbor Plain. They flew a drone over about five square kilometres at Kybo Station, and an AI trained on photos of earlier meteorites flagged likely rocks in the pictures. On the fourth day they picked up a 70 gram meteorite within 50 metres of the predicted line, which the team says is the first found this way.', 'Meteorite hunts usually mean lines of people walking the ground for days, and the team says the drone and AI search needs about a tenth of the labour and time.', NULL, NULL, '["People still checked the AI''s picks and threw out false alarms before walking to the rock.", "''First'' is the authors'' own claim, made in their paper in The Astrophysical Journal Letters.", "The ''one tenth of the labour and time'' figure is the team''s estimate in Curtin''s release, not a measured comparison.", "This was one successful search, not yet a routine method."]', 'space', 'in_a_trial', 'vision', 19, '["https://iopscience.iop.org/article/10.3847/2041-8213/ac66d4", "https://arxiv.org/abs/2203.01466", "https://www.curtin.edu.au/news/media-release/drones-and-artificial-intelligence-aid-hunt-for-fallen-meteorite-in-outback-wa/"]', NULL, 'in_bank', NULL, 53);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('ai-steadies-ligo-mirrors', 'evergreen', 'good', NULL, 'AI steadies the mirrors of a machine that listens for colliding black holes', 'LIGO detects ripples in space from colliding black holes by measuring tiny movements of its mirrors, and unwanted shaking of those mirrors drowns out the faintest signals. Researchers from Caltech, the Gran Sasso Science Institute in Italy and Google DeepMind built an AI method that steadies the mirrors, and tested it on LIGO itself. It cut the unwanted motion 30 to 100 times better than the usual methods alone, in a study published in the journal Science.', 'The AI learned a better way to hold the mirrors still than engineers had found by hand, which Caltech''s scientists say opens the door to detecting bigger black holes.', NULL, NULL, '["The authors call it a proof of concept. The test on the real detector lasted one hour.", "It is not yet in everyday use and has not yet led to any new detection.", "DeepMind is a company. The independent source is Caltech''s own LIGO page and the paper in Science.", "The test site (Livingston, Louisiana) appeared only in a search summary of DeepMind''s blog, which I did not open, so leave the site unnamed."]', 'space', 'in_a_trial', 'other', 13, '["https://www.ligo.caltech.edu/news/ligo20250908"]', NULL, 'in_bank', NULL, 54);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('satellite-ai-skips-the-clouds', 'evergreen', 'good', NULL, 'A small satellite uses AI to look ahead and skip photos that would only show cloud', 'In July 2025 NASA''s Jet Propulsion Laboratory tested AI on a briefcase-sized satellite called CogniSAT-6, built by the British company Open Cosmos. The satellite tilts to look about 500 kilometres ahead along its path, the AI on board decides whether the view is cloudy or clear, and it takes a picture of the ground only when it is clear. The whole decision takes 60 to 90 seconds with no human involved, and NASA says the cloud-dodging ability is now proven.', 'Clouds block the view for satellites like this up to two thirds of the time, and the onboard AI saves the effort for clear shots, so scientists get far more usable pictures of Earth.', NULL, NULL, '["This was a flight test, not routine use on a science mission, which NASA says is the end goal.", "Spotting wildfires, storms and eruptions from orbit are planned next tests, not results.", "The ''up to two thirds'' cloud figure and the claim of success are NASA''s own."]', 'space', 'in_a_trial', 'vision', 14, '["https://www.nasa.gov/missions/earth/how-nasa-is-testing-ai-to-make-earth-observing-satellites-smarter/"]', NULL, 'in_bank', NULL, 55);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('ai-finds-109000-new-moon-craters', 'evergreen', 'good', NULL, 'AI finds more than 109,000 craters on the Moon that nobody had catalogued', 'Researchers led from Jilin University in China taught an AI what craters look like using about 7,900 already known ones, then ran it over maps of the Moon made by China''s Chang''e-1 and Chang''e-2 orbiters. It found 109,956 new craters, more than a dozen times the number it started from, and the team worked out the rough age of nearly 19,000 of the larger ones. The results were published in Nature Communications.', 'Counting craters by eye is slow and experts disagree, and the AI did it across the Moon''s middle and lower latitudes, giving scientists a much fuller record of what has hit the Moon and when.', NULL, NULL, '["The new catalogue covers the Moon''s mid and low latitudes, not the poles.", "''New'' means not in the existing catalogue the team started from. The craters are old.", "Ages were estimated only for 18,996 craters wider than 8 km."]', 'space', 'in_the_lab', 'vision', 14, '["https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=PMCID:PMC7755906&resultType=core&format=json"]', NULL, 'in_bank', NULL, 56);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('ai-finds-72-missed-radio-bursts', 'evergreen', 'good', NULL, 'AI finds 72 mysterious radio flashes from deep space that astronomers had missed', 'Fast radio bursts are split-second flashes of radio waves from distant galaxies, and nobody is sure what makes them. Astronomers had already found 21 bursts in five hours of recordings of one source, about 3 billion light years away, made with the Green Bank Telescope in West Virginia. Gerry Zhang, a PhD student at the University of California, Berkeley, trained an AI on those and ran it over the same recordings, and it found 72 more.', 'The AI caught faint flashes that the standard search had missed in data that had already been combed, giving astronomers 93 bursts from one source to study instead of 21.', NULL, NULL, '["The 72 bursts were found in existing recordings from 26 August 2017, not in new observations.", "The work was done within Breakthrough Listen, a project that searches for signs of intelligent life. Nothing here suggests aliens.", "The finding does not explain what causes the bursts."]', 'space', 'in_the_lab', 'other', 12, '["https://greenbankobservatory.org/press-release/artificial-intelligence-uncovers-72-new-fast-radio-bursts-in-gbts-breakthrough-listen-data/", "https://arxiv.org/abs/1809.03043"]', NULL, 'in_bank', NULL, 57);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('blind-classroom-malawi', 'evergreen', 'good', NULL, 'A talking AI classroom helps blind pupils in Malawi study on their own', 'Staff Nyoni, a young Malawian who studied ICT, built Blind Classroom, an AI learning system that reads lessons aloud, asks questions and lets pupils answer by voice. It is being piloted at Chilanga School for the Blind and St Joseph Resource Centre in central Malawi, with backing from Save the Children. Yankho Maganga, 14, who used to rely on Braille and a teacher''s help, says she is now among the top performers in her class.', 'The AI turns written lessons into spoken ones a blind pupil can replay and answer by voice, so children at the two pilot schools can study without waiting for a teacher or Braille copies.', NULL, NULL, '["It is a pilot in two schools; the move to 14 schools is planned, not finished", "Yankho''s improved grades are her own account, not a measured study result", "Not all subjects are loaded into the system yet", "The article does not say which AI models it uses"]', 'accessibility', 'in_a_trial', 'voice', 18, '["https://dandc.eu/en/article/malawi-tool-blind%20students"]', NULL, 'in_bank', NULL, 58);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('keith-thomas-double-neural-bypass', 'evergreen', 'good', NULL, 'Brain implants and AI let a paralysed New York man feed himself and feel his sister''s hand', 'Keith Thomas, from Massapequa in New York, was paralysed from the chest down in a diving accident in 2020. In a trial at the Feinstein Institutes, surgeons put five small sensors in his brain, and AI reads the movements he intends and sends signals to his arm muscles, while sensors on his hand send touch back to his brain. Results published in Nature Medicine in July 2026 report that he now feeds himself, drinks from a cup and feels his sister''s hand and his dog''s fur.', 'The AI works out what Keith is trying to do from his brain signals and passes it round his injured spine, and that has given one man back the use and feeling of his hand.', NULL, NULL, '["One participant only", "The figures (arm strength up 86% and 62%) come from the institute''s press release; the journal paper itself was not opened", "It needed a 15-hour brain operation and he is not fully independent", "Do not call it a cure for paralysis"]', 'accessibility', 'in_a_trial', 'other', 22, '["https://www.biospace.com/press-releases/feinstein-institutes-technology-that-restores-movement-and-sensation-after-paralysis-featured-in-nature-medicine", "https://popsci.com/science/brain-computer-implant-paralysis-update", "https://time.com/6298543/paralysis-reversal-keith-thomas"]', NULL, 'in_bank', NULL, 59);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('blind-runner-solo-5k-central-park', 'evergreen', 'good', NULL, 'A blind runner completed a 5 km run alone in Central Park, guided by AI on his phone', 'Thomas Panek, who is blind and leads the charity Guiding Eyes for the Blind, ran 5 km on his own in New York''s Central Park in November 2020. A phone on his waistband used AI to spot a line marked on the path, and sounds in his headphones told him when he drifted left or right. He had needed guide dogs or human guides to run before that.', 'The AI in the phone did the job of a guide by watching the line and steering him with sound, which gave a blind runner the freedom to run alone.', NULL, NULL, '["It was a Google research project, not an app the public can download", "It only works where a line has been marked on the ground", "One runner on one prepared course"]', 'accessibility', 'in_a_trial', 'vision', 21, '["https://www.aljazeera.com/program/newsfeed/2020/11/23/blind-runner-completes-solo-5k-guided-by-ai/", "https://blog.google/outreach-initiatives/accessibility/project-guideline/"]', NULL, 'in_bank', NULL, 60);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('ai-suitcase-guides-blind-visitors-japan', 'evergreen', 'good', NULL, 'A suitcase that steers itself guides blind visitors round a museum in Japan', 'Chieko Asakawa, a blind IBM Fellow who leads the Miraikan science museum in Japan, came up with the AI Suitcase on a business trip. It looks like ordinary luggage, but it uses sensors and image-recognition AI to spot walls, obstacles and people, and it leads its user to a chosen place while the handle vibrates to signal turns. A regular pilot service began at Miraikan in April 2024, with daily tours, and a large field trial ran at Expo 2025 in Osaka.', 'The AI recognises people and obstacles and plans a safe route, so a blind person can walk through a busy building without a human guide.', NULL, NULL, '["It is a pilot service and field trials, not a product on sale", "Miraikan gives no figures for how many people have used it and no results from the Expo trial", "Tours follow set routes inside the museum"]', 'accessibility', 'in_a_trial', 'vision', 18, '["https://www.miraikan.jst.go.jp/en/lab/AIsuitcase/"]', NULL, 'in_bank', NULL, 61);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('terp-360-kenyan-sign-language-avatars', 'evergreen', 'good', NULL, 'A Kenyan app turns speech into sign language with lifelike 3D avatars', 'Elly Savatia of Kenya built Terp 360, an AI app that turns speech into sign language shown by 3D avatars. His team worked with Kenya''s deaf community to record more than 2,300 signs. In October 2025 it won the Royal Academy of Engineering''s Africa Prize for Engineering Innovation, worth £50,000, and Kenya''s Star newspaper reports that it has reached more than 2,000 deaf users.', 'The AI does the interpreting where there are too few human sign language interpreters, which helps deaf people follow what is said in classrooms and public services.', NULL, NULL, '["The figure of more than 2,000 users comes from the company''s side and was reported by The Star, not by the Royal Academy", "It translates speech into sign language, not sign language into speech", "No independent test of how accurate the signing is"]', 'accessibility', 'helping_people_now', 'language model', 20, '["https://www.raeng.org.uk/news/kenyan-innovator-elly-savatia-named-the-2025-africa-prize-for-engineering-innovation", "https://www.the-star.co.ke/health/2025-10-23-kenyan-creates-first-sign-language-app"]', NULL, 'in_bank', NULL, 62);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('gert-jan-oskam-walks-with-brain-spine-link', 'evergreen', 'good', NULL, 'A paralysed man walks again after AI links his brain to his spine', 'Gert-Jan Oskam was paralysed from the hips down in an accident in 2011. Researchers in Lausanne in Switzerland put implants in his skull and spine, and an AI program reads his intention to move from his brain signals and passes it to the nerves in his spine. A study in the journal Nature in May 2023 reported that he stands, walks and climbs stairs with the system, which stayed reliable for over a year, including at home.', 'The AI reads what he means to do and sends it past the injury, so his own thoughts control his legs again.', NULL, NULL, '["One participant only", "He walks with a walker or crutches, not unaided", "It took surgery and long physical therapy, and the team says it is probably not suited to restoring arm movement", "Sources differ on the kind of accident, so do not specify it"]', 'accessibility', 'in_a_trial', 'other', 22, '["https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=DOI:10.1038/s41586-023-06094-5&resultType=core&format=json", "https://www.irishtimes.com/health/your-wellness/2023/06/11/weve-captured-the-thoughts-of-gert-jan-and-translated-these-thoughts-into-a-stimulation-of-the-spinal-cord-to-reestablish-voluntary-movement"]', NULL, 'removed', NULL, 63);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('jennifer-wexton-ai-voice-in-congress', 'evergreen', 'good', NULL, 'A US congresswoman who lost her voice to illness spoke in Congress in her own voice, rebuilt by AI', 'Jennifer Wexton, a member of the US House of Representatives from Virginia, has progressive supranuclear palsy, a rare brain disease that took away her speech. Her office sent more than an hour of her old speeches to the company ElevenLabs, which built an AI copy of her voice within a few days. On 25 July 2024 she used it to address the House, which NPR reported was the first time an AI-cloned voice had been used on the House floor.', 'The AI rebuilt her own voice from old recordings, so she kept doing her job and sounded like herself instead of a robotic text reader.', NULL, NULL, '["The voice is a recreation from old recordings and she types what it says", "The illness itself is not treated", "NPR says it was a first for the House floor, not for any parliament anywhere", "Similar in kind to other voice-clone stories already in the bank, so space them apart"]', 'accessibility', 'helping_people_now', 'voice', 22, '["https://www.kunc.org/npr-news/2024-07-25/a-neurological-disease-stole-rep-jennifer-wextons-voice-ai-helped-her-get-it-back"]', NULL, 'in_bank', NULL, 64);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('speech-recognition-learns-parkinsons-voices', 'evergreen', 'good', NULL, 'Speech recognition got much better at understanding people with Parkinson''s after they taught it themselves', 'Researchers at the University of Illinois Urbana-Champaign recruited about 250 adults whose speech is affected by Parkinson''s disease, who recorded themselves on their own phones and computers. A speech recogniser trained on 151 hours of those recordings got about 24 in every 100 words wrong on new speakers with Parkinson''s, compared with about 36 in 100 for a system trained without them. The study was published in the Journal of Speech, Language, and Hearing Research and the recordings are shared with researchers, charities and companies.', 'Once the AI had heard enough speech from people with Parkinson''s it made far fewer mistakes with them, which matters to people who rely on voice controls and dictation.', NULL, NULL, '["It is a study result; it does not mean everyday voice assistants already work this well", "About a quarter of words were still wrong", "The exact error rates are 23.69% and 36.3%; the university rounds the gain to ''about 30% more accurate''"]', 'accessibility', 'in_the_lab', 'voice', 13, '["https://slcl.illinois.edu/news/2024-10-21t201245/automatic-speech-recognition-learned-understand-people-parkinsons-disease"]', NULL, 'in_bank', NULL, 65);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('live-transcribe-captions-for-deaf-people', 'evergreen', 'good', NULL, 'A deaf scientist helped build a free phone app that captions conversations as they happen', 'Dimitri Kanevsky, a Google research scientist who has been deaf since early childhood, worked with engineer Chet Gnegy on Live Transcribe, an Android app that turns speech around the phone into written captions in real time. Staff at Gallaudet University, a university for deaf and hard-of-hearing students, helped design and test it. Google released it in February 2019 with support for more than 70 languages and dialects.', 'AI speech recognition writes out what people are saying as they say it, so a deaf person follows a chat at a counter or a meeting with only a phone.', NULL, NULL, '["It is a Google product and the description comes largely from Google; Hearing Tracker''s report is the independent source", "Captions contain mistakes, and at launch the app relied on cloud-based speech recognition", "It launched as a limited beta on Android only", "No usage numbers were confirmed"]', 'accessibility', 'helping_people_now', 'voice', 19, '["https://blog.google/outreach-initiatives/accessibility/making-audio-more-accessible-two-new-apps/", "https://www.hearingtracker.com/news/google-live-transcribe-app"]', NULL, 'in_bank', NULL, 66);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('togo-novissi-ai-cash-aid', 'evergreen', 'good', NULL, 'Togo used AI and phone data to get emergency cash to its poorest people during Covid', 'When Covid hit in 2020, Togo launched Novissi, a programme that sent emergency cash to people''s mobile phones, but the country had no up-to-date list of who was poorest. Researchers used AI on satellite pictures to find the poorest areas and on phone use records to find the poorest people in them. A study in Nature in 2022 found this left 4 to 21% fewer needy people wrongly missed out than the area-based methods the government was considering.', 'The AI found people in need without a household survey that Togo did not have time for, so more of the money reached the poorest.', NULL, NULL, '["The 4 to 21% is against the simpler area-based options, not against an ideal system", "A full, up-to-date social register would have done better than the AI, by 9 to 35%, had one existed", "Do not attribute the whole programme''s reach of over half a million people to the AI part", "Researchers say it should not replace traditional methods when there is time and data"]', 'everyday_life', 'helping_people_now', 'other', 21, '["https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=DOI:10.1038/s41586-022-04484-9&resultType=core&format=json", "https://www.povertyactionlab.org/project/using-mobile-phone-and-satellite-data-target-togos-emergency-cash-transfer-program"]', NULL, 'in_bank', NULL, 67);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('chatgpt-cuts-teachers-planning-time-england', 'evergreen', 'good', NULL, 'Teachers in England planned lessons about a third faster with ChatGPT, with no drop in quality', 'A trial in England involved 259 science teachers in 68 secondary schools. Half were given ChatGPT and a guide to using it for planning lessons for 11 to 13 year olds, and half were asked not to use AI. The ChatGPT group spent 56 minutes a week on planning instead of 82, a saving of 31%, and an independent panel of teachers saw no noticeable difference in the quality of their materials.', 'The AI drafted quizzes, activity ideas and tailored materials, which gave teachers back about 25 minutes a week without worse lessons.', NULL, NULL, '["It covers Year 7 and 8 science planning only", "The quality check used a limited sample of materials", "Teachers were given a guide as well as the tool", "It measured teachers'' time, not pupils'' results"]', 'everyday_life', 'in_a_trial', 'language model', 15, '["https://schoolsweek.co.uk/using-chatgpt-can-cut-lesson-planning-by-31-eef-study"]', NULL, 'in_bank', NULL, 68);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('us-treasury-ai-cheque-fraud', 'evergreen', 'good', NULL, 'The US Treasury used AI to recover $1 billion in cheque fraud in a year', 'The US Treasury said in October 2024 that it had started using machine learning AI to spot fraud involving government cheques faster. In the year to September 2024 that work recovered $1 billion. It was part of more than $4 billion in fraud and wrongful payments that the Treasury prevented or recovered that year, up from $652.7 million the year before.', 'The AI flagged suspect cheques quickly enough for the money to be recovered, and that is public money returned to taxpayers.', NULL, NULL, '["Only the $1 billion from cheque fraud is tied to AI; the rest of the $4 billion came from other methods", "The figures are the Treasury''s own", "The total covers fraud and improper payments, not fraud alone"]', 'everyday_life', 'helping_people_now', 'other', 16, '["https://home.treasury.gov/news/press-releases/jy2650"]', NULL, 'in_bank', NULL, 69);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('plantvillage-nuru-cassava-disease-app', 'evergreen', 'good', NULL, 'A free phone app spots cassava disease better than farmers and farm advisers in East Africa', 'PlantVillage Nuru is a free phone app that uses AI to look at a cassava leaf through the camera and say whether the plant has a disease, with advice on what to do. Researchers tested it in Tanzania and western Kenya and published the results in Frontiers in Plant Science in December 2020. The app was right 65% of the time, compared with 40 to 58% for agricultural advisers and 18 to 31% for farmers, and it works without a phone signal.', 'The AI puts an expert eye in a farmer''s pocket, even where there is no signal, for a crop that many families depend on.', NULL, NULL, '["65% is well short of trained experts, who scored 81 to 95% in the same study", "It was weak on one disease, cassava brown streak, from a single leaf; checking six leaves gave 74 to 88%", "The study measured diagnosis, not whether harvests improved"]', 'everyday_life', 'in_a_trial', 'vision', 18, '["https://pmc.ncbi.nlm.nih.gov/articles/PMC7775399"]', NULL, 'in_bank', NULL, 70);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('nigeria-ai-tutor-after-school-trial', 'evergreen', 'good', NULL, 'Pupils in Nigeria made big gains in English after six weeks with an AI tutor', 'In June and July 2024, secondary school pupils in Edo State in Nigeria took part in a six-week after-school programme where they used an AI chatbot as a tutor, guided by their teachers. Pupils were picked at random to join or not. The World Bank, which ran the trial, reported that those who joined did clearly better in English, AI knowledge and digital skills, and that girls, who started behind, gained the most.', 'The AI gave each pupil a patient tutor to practise with while teachers guided the sessions, in schools where one-to-one help is rare.', NULL, NULL, '["The World Bank''s ''nearly two years of learning'' claim is its own conversion of a 0.3 standard deviation gain; do not present it as two years of schooling delivered", "The comparison group got no extra lessons, so critics note the gain mixes AI with extra teaching time", "Teachers led the sessions; it was not AI alone", "Reported in a World Bank blog and working paper, not yet in a peer-reviewed journal", "Six weeks only, long-term effect unknown"]', 'everyday_life', 'in_a_trial', 'language model', 21, '["https://blogs.worldbank.org/en/education/From-chalkboards-to-chatbots-Transforming-learning-in-Nigeria"]', NULL, 'removed', NULL, 71);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('japan-ai-lost-property-keio', 'evergreen', 'good', NULL, 'A Tokyo railway returned nearly three times as many lost items after AI took over the lost property desk', 'Keio, a railway company in Tokyo with 69 stations, gets about 500 enquiries a day about lost property. Since 2023 its staff have photographed each found item, and AI from the Tokyo start-up Find records its colour, shape and size so owners can search by picture and chat in four languages. In Keio''s trial the share of items returned to their owners nearly tripled and enquiries by phone and at station counters fell by about a third.', 'The AI describes and matches items from a photo, so a plain umbrella or wallet gets back to its owner and station staff spend about a minute logging it, not ten.', NULL, NULL, '["The results come from Keio''s trial as reported on the Tokyo government''s news site; exact return rates were not confirmed", "The ten minutes to one minute figure is for umbrellas", "33 companies use it; do not say all of Japan"]', 'everyday_life', 'helping_people_now', 'vision', 23, '["https://www.tokyoupdates.metro.tokyo.lg.jp/en/post-1641/"]', NULL, 'in_bank', NULL, 72);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('petco-love-lost-ai-reunites-pets', 'evergreen', 'good', NULL, 'AI photo matching has reunited more than 200,000 lost pets with their owners in the US', 'Love Lost is a free US database run by the charity Petco Love, where owners upload a photo of a missing pet and AI compares its face, coat and markings with photos from about 3,000 shelters and from social media. The database says it has reunited more than 200,000 pets and owners since 2021. When Millie, a dog who slipped her collar in Manhattan in 2024, was hit by a car and taken to a vet in New Jersey, the system matched her photo and her owner Michael Bown had her back within about 15 hours.', 'The AI recognises one animal among huge numbers of shelter and social media photos, which gets pets home that paper posters would not have found.', NULL, NULL, '["The 200,000 figure is the charity''s own count, reported by the Washington Post", "Petco Love is linked to the pet shop chain Petco", "Animal charities say it does not replace microchipping"]', 'everyday_life', 'helping_people_now', 'vision', 23, '["https://www.spokesman.com/stories/2026/mar/22/these-people-used-ai-to-help-find-their-lost-pets", "https://www.cbsnews.com/news/ai-lost-pets-petco-love-facial-recognition"]', NULL, 'in_bank', NULL, 73);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('te-hiku-maori-speech-ai', 'evergreen', 'good', NULL, 'A Māori radio station built its own AI that understands the Māori language, using voices from its community', 'Te Hiku Media, a Māori broadcaster in the Far North of New Zealand, built AI tools that write down spoken te reo Māori, give feedback on pronunciation and turn text into speech. More than 2,500 people signed up in ten days to read phrases aloud, which gave over 300 hours of recordings, and the data is held under a licence that keeps its use for the benefit of Māori. The tools run a transcription service and help about 20 Māori radio stations search more than 30 years of archive recordings.', 'The AI makes decades of recordings in an endangered language searchable and helps learners with pronunciation, and the community that speaks the language owns it.', NULL, NULL, '["The 92% accuracy figure is Te Hiku''s own claim and has not been independently tested, so leave it out or attribute it", "Most detail on the data comes from a blog by Nvidia, whose tools Te Hiku used", "No confirmed date for the recording campaign"]', 'everyday_life', 'helping_people_now', 'voice', 20, '["https://www.rnz.co.nz/news/top/531303/why-google-maps-can-t-pronounce-maori-place-names", "https://blogs.nvidia.com/blog/te-hiku-media-maori-speech-ai/"]', NULL, 'in_bank', NULL, 74);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('brazil-ai-essay-feedback-espirito-santo', 'evergreen', 'good', NULL, 'A Brazilian state gave every final-year pupil an AI writing coach after it raised exam scores', 'In 2019, about 12,000 final-year pupils in 110 state schools in Espírito Santo in Brazil used Letrus, an AI tool that gives instant feedback on practice essays for the national university entrance exam. A randomised trial across 178 schools found their essay scores rose by about 17 points out of 1,000, which closed about 9% of the gap with private school pupils. In 2022 the state announced it would offer the tool to every final-year pupil in its state schools, and more than 100,000 have been enrolled since 2020.', 'The AI gave each pupil prompt, personal feedback that busy teachers had no time to write, and pupils then wrote more and talked more with their teachers about their essays.', NULL, NULL, '["The gain is modest: 17 points in 1,000 and 9% of the gap", "The trial result is in a working paper and a J-PAL case study, not confirmed as peer-reviewed", "Only about half to 60% of enrolled pupils submitted essays in the roll-out years", "Enrolment figures come partly from the company and the state"]', 'everyday_life', 'helping_people_now', 'language model', 19, '["https://www.povertyactionlab.org/case-study/artificial-intelligence-strengthen-high-school-students-writing-skills"]', NULL, 'removed', NULL, 75);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('ithaca-greek-inscriptions', 'evergreen', 'good', NULL, 'AI helps historians fill the gaps in damaged ancient Greek inscriptions', 'Researchers from DeepMind and the universities of Venice, Oxford and Athens built an AI called Ithaca that suggests the missing words in damaged ancient Greek inscriptions, and estimates where and when each one was carved. Working alone, historians restored the test texts correctly 25% of the time. Working with Ithaca, they got 72% right. The results were published in Nature.', 'The AI turned a slow guessing job into a partnership, nearly tripling how often historians restored a damaged text correctly, and it places inscriptions to within 30 years of their accepted dates.', NULL, NULL, '["The figures come from tests on inscriptions where the answer was already known, not from new finds.", "Ithaca on its own scored 62% on restoring text, so say it helps historians, not that it replaces them.", "DeepMind is a company: the independent source is the peer-reviewed Nature paper with university co-authors.", "Its re-dating of some Athenian decrees touches a live debate among historians, so do not call it settled."]', 'science', 'in_the_lab', 'language model', 14, '["https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=DOI:10.1038/s41586-022-04448-z&resultType=core&format=json"]', NULL, 'in_bank', NULL, 76);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('dead-sea-scrolls-ai-dating', 'evergreen', 'good', NULL, 'AI that studies handwriting suggests many Dead Sea Scrolls are older than thought', 'A team led from the University of Groningen in the Netherlands trained an AI called Enoch on the handwriting of 24 Dead Sea Scroll samples whose age had been measured by radiocarbon dating. They then used it to estimate the age of 135 scrolls that had never been dated. Many came out older than scholars had estimated from the handwriting by eye, and the study was published in PLOS One.', 'Only 24 samples had a measured radiocarbon age to learn from. The AI used them to give an age estimate for 135 more scrolls from their handwriting alone.', NULL, NULL, '["The model learned from only 24 dated samples and its typical error is about 28 to 31 years.", "Handwriting experts judged about 79% of its estimates realistic, not all of them.", "Press coverage reported that some scroll scholars are not convinced by the earlier dates, so say ''suggests'', not ''proves''.", "Do not say the Bible has been re-dated."]', 'science', 'in_the_lab', 'vision', 17, '["https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=TITLE:%22Dating%20ancient%20manuscripts%20using%20radiocarbon%20and%20AI-based%20writing%20style%20analysis%22&resultType=core&format=json"]', NULL, 'in_bank', NULL, 77);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('raphael-joseph-face', 'evergreen', 'good', NULL, 'AI finds that one face in a Raphael painting was probably painted by someone else', 'Researchers from the universities of Bradford, Nottingham and Stanford trained an AI on authenticated paintings by Raphael and pointed it at the Madonna della Rosa, which hangs in the Prado in Madrid. Tested as a whole, the painting gave no clear answer. Tested piece by piece, most of it came out as Raphael''s work, but the face of Joseph most likely did not. The study was published in the journal Heritage Science.', 'The AI gave art experts a new kind of evidence about who painted what, and it pointed to one specific face in a famous picture.', NULL, NULL, '["The researchers say the result is not enough on its own to decide who painted what. It is one tool to help experts.", "The 98% accuracy figure is the team''s own test result for the model.", "Giulio Romano is only suggested as a possible painter of Joseph''s face.", "Some art historians were dismissive of the work in press coverage, and the Prado has not changed its attribution as far as we found.", "The journal page could not be opened directly: facts were confirmed on the University of Nottingham''s own news page."]', 'science', 'in_the_lab', 'vision', 17, '["https://www.nottingham.ac.uk/news/madonna-della-rosa"]', NULL, 'in_bank', NULL, 78);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('night-watch-missing-edges', 'evergreen', 'good', NULL, 'AI repaints the edges of Rembrandt''s Night Watch that were cut off 300 years ago', 'In 1715 Rembrandt''s Night Watch was trimmed on all four sides to fit a wall in Amsterdam''s City Hall, and the strips were never found. In June 2021 the Rijksmuseum in Amsterdam showed the painting complete for the first time in 300 years. Its scientists had taught an AI Rembrandt''s technique and colours, then had it recreate the missing parts from a small copy made in the 17th century. The new pieces were printed and hung around the original.', 'The AI turned another painter''s small copy into Rembrandt''s own style at full size, so visitors saw the picture as he composed it, including 64 centimetres on the left that had been lost.', NULL, NULL, '["The added pieces are printed reconstructions placed around the painting, not recovered Rembrandt paint.", "The display was temporary, for some months in 2021, and the museum said it would not add the pieces in the real restoration.", "The reconstruction rests on a 17th-century copy attributed to Gerrit Lundens."]', 'science', 'in_a_trial', 'vision', 21, '["https://www.rijksmuseum.nl/en/press/press-releases/for-the-first-time-in-300-years-the-night-watch-is-complete-again"]', NULL, 'in_bank', NULL, 79);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('lope-de-vega-lost-play', 'evergreen', 'good', NULL, 'AI spots an unknown play by Lope de Vega among anonymous manuscripts in Spain''s National Library', 'Researchers from the universities of Valladolid and Vienna used AI to transcribe about 1,300 plays from Spain''s Golden Age, then compared the wording of each with known authors. One anonymous manuscript in the National Library of Spain, La francesa Laura, matched Lope de Vega, one of Spain''s greatest playwrights. The researchers then checked it by traditional methods, including its verse, and the library announced the find in early 2023.', 'The play had sat in the library''s catalogue since 1882 with no author. AI read the handwriting in hours and picked it out from the pile, which let scholars focus their checking on the right manuscript.', NULL, NULL, '["The attribution rests on writing style, checked by scholars. No document names Lope as the author.", "Say ''attributed to'', and that the play dates from the last years before his death in 1635.", "The National Library''s own announcement could not be opened: facts were confirmed on University of Valladolid and University of Innsbruck pages and in news reports."]', 'science', 'in_the_lab', 'other', 17, '["https://bibliotecahistorica.blogs.uva.es/2023/02/23/el-nuevo-hallazgo-de-lope-de-vega/", "https://www.uibk.ac.at/de/newsroom/2023/ki-entdeckt-bisher-unbekannte-komodie/", "https://www.eldebate.com/cultura/20230131/inteligencia-artificial-descubre-autor-obra-anonima-fondos-biblioteca-nacional-lope-vega_90151_amp.html", "https://www.thestar.com.my/lifestyle/culture/2023/02/02/ai-uncovers-unknown-play-by-spanish-great-in-library-archive"]', NULL, 'in_bank', NULL, 80);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('henry-viii-shakespeare-fletcher', 'evergreen', 'good', NULL, 'Machine learning backs the old theory that Shakespeare shared the writing of Henry VIII', 'Petr Plecháč of the Czech Academy of Sciences trained a machine learning model on the favourite words and verse rhythms of Shakespeare and of a second playwright named Fletcher. He ran it across the play Henry VIII passage by passage, ignoring scene breaks. The result strongly supported the split between the two writers that a scholar named James Spedding had proposed long before, and the study was published in Digital Scholarship in the Humanities.', 'Scholars had argued over who wrote which parts of the play using their own ear for style. The AI measured word habits and rhythm across the whole text and came to the same division independently.', NULL, NULL, '["It supports an existing theory. It did not discover the collaboration.", "The paper''s summary does not give a percentage for each writer, so do not say ''half''.", "This is statistical evidence about style, not a document proving who wrote what."]', 'science', 'in_the_lab', 'other', 14, '["https://academic.oup.com/dsh/article/36/2/430/5880040"]', NULL, 'in_bank', NULL, 81);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('babylon-hymn-pieced-together', 'evergreen', 'good', NULL, 'AI helps piece together a lost hymn in praise of Babylon', 'Enrique Jiménez of LMU Munich, working with the University of Baghdad, rediscovered a hymn in praise of the ancient city of Babylon, written around 1000 BCE and about 250 lines long. His team is digitising clay tablet fragments from around the world and uses AI to find pieces that belong to the same text. The AI turned up 30 more manuscripts of the hymn, which let the scholars fill in the missing parts. The work was published in the journal Iraq.', 'Matching scattered fragments by hand would have taken decades, the lead researcher said. With AI the team recovered a poem describing Babylon''s buildings, the Euphrates bringing spring to the fields, and the city''s priestesses.', NULL, NULL, '["''Would have taken decades'' is the researcher''s own estimate.", "The AI matched fragments. Scholars did the reading and translation.", "Facts come from LMU''s own news page describing the peer-reviewed paper (DOI 10.1017/irq.2024.23), which was not opened directly."]', 'science', 'in_the_lab', 'other', 16, '["https://www.lmu.de/en/newsroom/news-overview/news/hymn-to-babylon-discovered.html"]', NULL, 'in_bank', NULL, 82);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('pig-grunts-emotions', 'evergreen', 'good', NULL, 'AI learns to tell a happy pig from an unhappy one by its grunts', 'A team of European researchers, including scientists at the University of Copenhagen and ETH Zurich, recorded 7,414 calls from 411 pigs in situations from birth to slaughter. They trained an AI to tell from the sound alone whether the pig was in a good or bad situation, and it got it right 91.5% of the time. The study was published in Scientific Reports.', 'A standard statistical method managed only about 62% on the same recordings. The authors say the result shows an automated system for checking pig welfare on farms can be built.', NULL, NULL, '["Nothing is in use on farms yet. This is a study on recorded calls.", "The AI sorts calls into positive or negative situations as defined by the researchers. It does not read a pig''s mind.", "Its accuracy at naming the exact situation was lower, at 81.5%."]', 'science', 'in_the_lab', 'voice', 15, '["https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=TITLE:%22Classification%20of%20pig%20calls%20produced%20from%20birth%20to%20slaughter%22&resultType=core&format=json"]', NULL, 'in_bank', NULL, 83);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('fusion-plasma-ai-control', 'evergreen', 'good', NULL, 'AI learns to hold and shape the super-hot gas inside a Swiss fusion machine', 'Scientists at EPFL''s Swiss Plasma Center in Lausanne and DeepMind trained an AI in a simulator to control the magnets of a fusion machine called TCV. They then let it run the real machine, where it held plasma, a gas heated to hundreds of millions of degrees, in a range of shapes. It also kept two separate plasmas going in the machine at the same time. The results were published in Nature.', 'One AI system learned to work the magnets for many different plasma shapes. The paper says this reduces the design effort needed each time scientists want a new one.', NULL, NULL, '["This is a research machine that makes no electricity. Do not suggest fusion power is close.", "DeepMind is a company: the independent sources are the Nature paper and EPFL."]', 'science', 'in_the_lab', 'other', 14, '["https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=TITLE:%22Magnetic%20control%20of%20tokamak%20plasmas%20through%20deep%20reinforcement%20learning%22&resultType=core&format=json", "https://actu.epfl.ch/news/epfl-and-deepmind-use-ai-to-control-plasmas-for-nu"]', NULL, 'in_bank', NULL, 84);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('dinosaur-footprint-ai', 'evergreen', 'good', NULL, 'AI trained on 2,000 fossil footprints helps work out which dinosaur made them', 'Researchers led by the Helmholtz-Zentrum Berlin, working with the University of Edinburgh, trained an AI on nearly 2,000 fossil footprints. It agreed with human experts about 90% of the time on what kind of dinosaur made a track, including ones experts argue over. It also found that some tracks more than 200 million years old share features with the feet of birds. The study was published in PNAS, and an app called DinoTracker lets anyone upload a photo or sketch of a footprint for analysis.', 'Fossil footprints are common but hard to read, and experts often disagree. The AI gives a consistent second opinion and puts a tool once limited to specialists in the hands of anyone who finds a track.', NULL, NULL, '["The bird-like tracks have two explanations in the source: birds began much earlier than thought, or some early dinosaurs simply had bird-like feet. Do not pick one.", "''About 90%'' is agreement with experts, who can themselves be wrong.", "The source does not say whether the app is free."]', 'science', 'in_the_lab', 'vision', 17, '["https://www.ed.ac.uk/news/ai-sheds-light-on-mysterious-dinosaur-footprints"]', NULL, 'in_bank', NULL, 85);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('taiwan-ecg-alert-fewer-deaths', 'evergreen', 'good', NULL, 'AI heart-trace alerts cut deaths among hospital patients in a Taiwan trial', 'Doctors at Tri-Service General Hospital in Taipei ran a trial with 39 physicians and 15,965 patients. An AI read each patient''s routine heart trace and sent the doctor a warning when it judged the patient at high risk of dying. Within 90 days, 3.6% of patients whose doctors got the alerts had died, against 4.3% of those whose doctors did not. The trial was published in Nature Medicine.', 'The AI picked out the patients in most danger from a routine heart trace and warned their doctors. Fewer of those doctors'' patients died, in a randomised trial.', NULL, NULL, '["One hospital system in Taiwan. It has not yet been repeated elsewhere as far as we found.", "The gain was concentrated in patients the AI flagged as high risk.", "The authors say exactly how the alerts led to fewer deaths still needs explaining.", "Say 3.6% against 4.3%, not ''slashed'' or ''halved''."]', 'health', 'in_a_trial', 'other', 21, '["https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=DOI:10.1038/s41591-024-02961-4&resultType=core&format=json"]', NULL, 'in_bank', NULL, 86);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('mayo-ecg-weak-heart-pump', 'evergreen', 'good', NULL, 'AI reading routine heart traces helps family doctors catch weak hearts earlier', 'Mayo Clinic ran a trial across 45 clinics and hospitals in Minnesota and Wisconsin with 22,641 adults who were having a routine heart trace. For half of the care teams, an AI read the trace and told the doctor when it saw signs of a weak heart pump. Doctors who got the AI result found more new cases, 2.1% of patients against 1.6%. The trial was published in Nature Medicine.', 'The AI found a hidden warning in a test patients were already having, so more people with a weak heart were diagnosed, with no significant rise in follow-up heart scans overall.', NULL, NULL, '["The rise is from 1.6% to 2.1% of patients: real but modest.", "The trial measured new diagnoses, not whether patients lived longer."]', 'health', 'in_a_trial', 'other', 15, '["https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=DOI:10.1038/s41591-021-01335-4&resultType=core&format=json"]', NULL, 'in_bank', NULL, 87);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('pregnancy-ultrasound-novices-zambia', 'evergreen', 'good', NULL, 'With an AI handheld scanner, beginners date pregnancies as well as trained sonographers', 'Researchers from the University of North Carolina and the University of Zambia tested a handheld ultrasound probe with built-in AI on 400 pregnant people in Lusaka, Zambia, and Chapel Hill in the United States. People with no training in ultrasound swept the probe across the belly and the AI estimated how far along the pregnancy was. Their estimates were off by 3.2 days on average, against 3.0 days for trained sonographers. The study was published in JAMA.', 'The AI did the skilled part of the scan, so someone with no ultrasound training got an answer within a fraction of a day of a trained sonographer''s.', NULL, NULL, '["This was a study at two sites, not routine use.", "The main test covered scans between 14 and 27 weeks of pregnancy.", "It estimates how far along a pregnancy is. It does not check the baby''s health.", "The pregnancies studied were single babies with no known problems."]', 'health', 'in_a_trial', 'vision', 21, '["https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=AUTH:%22Stringer%20JSA%22%20AND%20TITLE:%22gestational%20age%22%20AND%20JOURNAL:%22JAMA%22%20AND%20PUB_YEAR:2024&resultType=core&format=json"]', NULL, 'in_bank', NULL, 88);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('ai-designed-lung-drug-trial', 'evergreen', 'good', NULL, 'A drug found with AI improves breathing in a lung disease trial in China', 'Rentosertib is a drug for idiopathic pulmonary fibrosis, a disease that scars the lungs. The company Insilico Medicine found it using generative AI. In a trial of 71 patients run from Peking Union Medical College Hospital with other Chinese hospitals, people on the highest dose for 12 weeks gained 98 millilitres of breathing capacity on average, while those on a dummy pill lost 20. The trial was published in Nature Medicine.', 'A medicine that began with an AI system has now been tested against a dummy pill in patients, and the top-dose group''s breathing improved while the dummy pill group''s got worse.', NULL, NULL, '["Small, early trial: 71 patients over 12 weeks, mainly testing safety.", "The breathing gain is in the top-dose group of 18 people and needs a larger trial to confirm.", "Most patients in every group, including the dummy pill group, reported side effects, and some stopped because of liver problems or diarrhoea.", "The drug is not approved anywhere.", "Insilico is a company: the independent source is the peer-reviewed paper with hospital investigators."]', 'health', 'in_a_trial', 'other', 16, '["https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=TITLE:%22A%20generative%20AI-discovered%20TNIK%20inhibitor%20for%20idiopathic%20pulmonary%20fibrosis%22&resultType=core&format=json"]', NULL, 'in_bank', NULL, 89);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('tb-xray-ai-who', 'evergreen', 'good', NULL, 'AI that reads chest X-rays for tuberculosis is now backed by the World Health Organization', 'Since 2021 the World Health Organization has recommended software that reads chest X-rays to screen people aged 15 and over for tuberculosis, and in June 2025 it said six products met its standards. In a study of 23,954 people at three screening centres in Dhaka, Bangladesh, five AI programs were compared with three radiologists, and all five did significantly better. Anyone the software flags still gets a confirming test before treatment.', 'WHO calls screening with chest X-rays and this software essential for finding tuberculosis cases that are being missed. In the Dhaka study the AI halved the number of confirming tests needed while still catching more than 90% of cases.', NULL, NULL, '["The AI screens. It does not diagnose: a positive result needs a confirming test.", "WHO does not recommend it for children under 15.", "The Dhaka study tested the programs on X-rays taken between 2014 and 2016, not in live use.", "The WHO page does not name the countries using it, so do not name any."]', 'health', 'helping_people_now', 'vision', 18, '["https://www.who.int/news/item/11-06-2025-who-approves-six-software-products-for-computer-aided-detection-of-tb-on-chest-x-ray", "https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=TITLE:%22Tuberculosis%20detection%20from%20chest%20x-rays%20for%20triaging%20in%20a%20high%20tuberculosis-burden%20setting%22&resultType=core&format=json"]', NULL, 'in_bank', NULL, 90);
INSERT INTO stories (id, origin, lane, added, headline, what_happened, why_its_good, bad_news, flip_kind, careful, topic, stage, technology, total, sources, line, status, published_on, position) VALUES ('baricitinib-covid-ai-suggestion', 'evergreen', 'good', NULL, 'An arthritis pill that an AI search flagged for Covid in February 2020 went on to save lives', 'In February 2020 scientists at the London company BenevolentAI, with a doctor from Imperial College London, searched the company''s store of medical knowledge, which is built using machine learning, for approved drugs to try against the new coronavirus. They named baricitinib, an arthritis pill, in a letter in The Lancet. In the RECOVERY trial of 8,156 hospital patients, 12% of those given baricitinib died within 28 days against 14% given usual care. In January 2022 the World Health Organization strongly recommended it for severe Covid.', 'The AI-built search pointed to a pill that was already approved for other uses, in the first weeks of the outbreak, so there was a candidate ready for trials.', NULL, NULL, '["The AI produced the suggestion. Large trials run by others proved it.", "The letter says the knowledge store uses machine learning: people chose baricitinib from the shortlist it produced.", "RECOVERY showed 12% against 14% deaths, a modest gain, and the drug is given alongside steroids.", "BenevolentAI is a company: the independent sources are the RECOVERY trial and WHO."]', 'health', 'helping_people_now', 'other', 21, '["https://www.ebi.ac.uk/europepmc/webservices/rest/PMC7137985/fullTextXML", "https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=TITLE:%22Baricitinib%20in%20patients%20admitted%20to%20hospital%20with%20COVID-19%20(RECOVERY)%22&resultType=core&format=json", "https://www.who.int/news/item/14-01-2022-who-recommends-two-new-drugs-to-treat-covid-19"]', NULL, 'removed', NULL, 91);
